begin;

-- Georgian College (Barrie, Ontario): correction of the existing unpublished record.
--
-- The seeded record held placeholder data: 4 invented diploma rows with round-number
-- tuition, 2 scholarships that do not exist, a null overview, null intakes and campuses,
-- and international_students stored as the fraction 0.28 instead of a percentage (the same
-- bug found on Braemar College). Everything below replaces that with researched data.
--
-- Sources: georgiancollege.ca throughout. Programs were read from each program's own page
-- (program code, duration, credential, delivery method, intake terms and description), the
-- academic area from each page's related-programs link, tuition bands and the entrance
-- scholarship from the international finance and fees page, and English requirements and
-- the application process from the international admissions page.
--
-- Scope (confirmed with user): the 122 full-time, on-campus, credential-bearing programs.
-- Excluded are part-time-only and online-only offerings, 5 micro-credentials and 6
-- Recognition of Achievement short courses, none of which support a study permit. Also
-- excluded is Supply Chain Management - Global, whose page states there are currently no
-- planned intakes.
--
-- Tuition: Georgian publishes international fees as a range per credential type rather
-- than per program, so tuition_fee_per_year carries that range and each description notes
-- that program-specific fees may apply. Application fee CAD 100, deposit CAD 2,500.
--
-- acceptance_rate is set to null: the seeded value of 80 was not published by Georgian and
-- could not be verified. ranking stays null, as Ontario colleges are not world-ranked.
--
-- is_published is deliberately NOT changed by this script. This record already has a logo
-- and cover image, so once you are happy with the data you can publish it with:
--   update public.universities set is_published = true where slug = 'georgian-college';

update public.universities set
  short_description = 'Georgian College is a public Ontario college in Barrie with seven locations and more than 130 career-focused programs, from certificates and diplomas to graduate certificates and honours bachelor degrees, with over 5,500 international students from 92 countries and a 90.3 per cent graduate employment rate.',
  overview = 'Georgian College is a publicly funded Ontario college founded in 1967 and headquartered in Barrie, about an hour north of Toronto. It teaches roughly 13,500 full-time students across seven locations, with the main Barrie campus supported by sites in Barrie Downtown, Midland, Orangeville, Owen Sound, Muskoka and South Georgian Bay. More than 5,500 of its students are international, coming from 92 countries and speaking over 30 languages, with India, Nepal and the Philippines the largest sources.

The college runs more than 130 career-focused programs across 13 academic areas, spanning Ontario College Certificates, two and three-year diplomas and advanced diplomas, one and two-year graduate certificates for students who already hold a credential, and six honours bachelor degrees. Every program is built around hands-on learning with a formal work-integrated component, supported by a network of co-op employers, and the college holds 370 transfer agreements with 85 institutions for students who want to continue to a university degree.

Georgian reports a graduate employment rate of 90.3 per cent within six months of graduation, above the provincial average, a record it has held for 25 consecutive years. It is the first and only college in Canada designated a changemaker college by Ashoka U for its work in social innovation. International students entering eligible programs are automatically considered for the International Entrance Scholarship, and once enrolled can apply to more than 750 further awards each year.',
  city = 'Barrie, ON',
  founded_year = 1967,
  total_students = 13544,
  number_of_campuses = 7,
  acceptance_rate = null,
  graduate_employability = 90.3,
  international_students = 41,
  intake_months = 'September, January, May',
  tuition_fee_min = 16990,
  tuition_fee_max = 29200,
  tuition_currency = 'CAD',
  has_on_campus = true,
  has_online = true,
  has_hybrid = true,
  updated_at = now()
where slug = 'georgian-college';

-- Rename the 4 placeholder programs onto their real Georgian counterparts, preserving row ids.
with uni as (select id from public.universities where slug = 'georgian-college')
update public.programs p
set
  slug = v.newslug, name = v.name, degree_level = v.degree_level::"DegreeType", field = v.field,
  campus = v.campus, application_fee = 'CAD 100', tuition_fee_per_year = v.tuition,
  duration_years = v.duration, intake_months = v.intake,
  entry_requirements = case v.entry_key
    when 'degree' then 'Ontario Secondary School Diploma or equivalent with the required Grade 12 subject prerequisites, including Grade 12 English and Mathematics. International Baccalaureate courses can satisfy Grade 12 requirements, and highly competitive degree programs may require a grade of 5 or higher. English proficiency for international applicants: IELTS Academic 6.5, TOEFL iBT 89, PTE 61, Duolingo 120, CAEL 60, or Cambridge C1 Advanced 175. Test results must be no more than two years old.'
    when 'grad' then 'A completed college diploma or university degree, evidenced by college or university transcripts showing graduation, plus a resume detailing relevant experience and a letter of intent stating the reason for applying. English proficiency for international applicants: IELTS Academic 6.5, TOEFL iBT 89, PTE 61, Duolingo 130, CAEL 60, or Cambridge C1 Advanced 175. Test results must be no more than two years old.'
    else 'Ontario Secondary School Diploma or equivalent, with secondary school transcripts showing proof of graduation, subjects taken and grades received. Grade 12 English and Mathematics credits are required. International Baccalaureate courses can satisfy Grade 12 requirements at a minimum grade of 4. English proficiency for international applicants: IELTS Academic 6.0, TOEFL iBT 79, PTE 58, Duolingo 110, CAEL 60, or Cambridge C1 Advanced 170. Test results must be no more than two years old.'
  end,
  learn_more_url = v.learn_more_url, description = v.description, updated_at = now()
from uni, (values
  ('georgian-diploma-business-administration', 'business-co-op-georgian', 'Business', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-co-op', 'Ontario College Diploma, Co-op at Georgian College, program code BUSG, in the Business and Management academic area. Delivered in-person and hybrid option at the Barrie campus. Students acquire a foundational knowledge of the basics of business, with a focus on managing people and processes. Courses in economics, accounting, marketing, and human resources lay the groundwork for future careers and further studies. Individual courses provide the student with the fundamental knowledge and skills required to get to work. Upon graduation, students may launch their career or spring-board into further studies. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('georgian-diploma-computer-programming', 'computer-programming-georgian', 'Computer Programming', 'DIPLOMA', 'Computer Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/computer-programming', 'Ontario College Diploma, Co-op at Georgian College, program code CMPG, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. In this program, students focus on computer programming, web development, and designing data-driven systems. Students learn how to write code in a variety of programming languages such as Arduino, ASP.NET, C#, Java, JavaScript, HTML/CSS, PHP and Swift. Students gain experience developing software for diverse platforms including embedded systems, desktop, mobile and mainframe systems. With a strong emphasis on business and entrepreneurial values, students gain experience in problem solving, troubleshooting and system building through a series of applied assignments, projects and co-op work terms. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('georgian-diploma-mechanical-engineering-technology', 'mechanical-engineering-technology-georgian', 'Mechanical Engineering Technology', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/mechanical-engineering-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code METY, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. Mechanical technology is a cornerstone of sophisticated and advanced economies. You learn the skills to apply scientific and engineering principles to solve mechanical engineering related problems. You undertake the design and fabrication of mechanical apparatus and systems, including automation and control systems, manufacturing processes, a dditive manufacturing technologies and material handling. Conventional and computerized numerical control (CNC) machining, interpreting engineering drawings, including metrology and geometric dimensioning and tolerancing (GD&T) are a part of your technologist skill set preparing you for the needs of industry today. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('georgian-diploma-early-childhood-education', 'early-childhood-education-georgian', 'Early Childhood Education', 'DIPLOMA', 'Human Services', 'Barrie, Owen Sound, Orangeville', 'CAD 16,990 to 29,200/year', 2.0, 'September, January, May', 'diploma', 'https://www.georgiancollege.ca/academics/programs/early-childhood-education', 'Ontario College Diploma at Georgian College, program code ECED, in the Human Services academic area. Delivered in person at the Barrie, Owen Sound, Orangeville campus. Within this program''s unique blend of theoretical knowledge and practical experience, students prepare to work with children (birth to 12 years old) and their families. Students learn how to support children''s holistic development and facilitate their adaptation to the challenges of everyday life. Students acquire the skills to be responsive caregivers while respecting diversity and the rights of children and families. They discover the multifaceted benefits of play-based learning through experiential courses that focus on outdoor learning, creative expression, and science and technology. Emphasis is placed on partnerships with families, other professionals, and community programs, as these form the foundation of working in the field of early learning and care. This approach to learning reflects the view that children are curious, capable and skilled and grow up in families with diverse social, linguistic and cultural backgrounds. Through two field placements, students have the opportunity to apply their knowledge and transfer their skills as they engage with children and adults in early years learning settings within the community. Students develop a range of abilities and best practices crucial for success in the various learning environments they may find employment in within the field of early childhood education. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.')
) as v(oldslug, newslug, name, degree_level, field, campus, tuition, duration, intake,
  entry_key, learn_more_url, description)
where p.university_id = uni.id and p.slug = v.oldslug;

-- The remaining 118 programs.
insert into public.programs (id, university_id, name, slug, degree_level, field, campus, application_fee,
  tuition_fee_per_year, duration_years, intake_months, entry_requirements, learn_more_url, description,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.slug, v.degree_level::"DegreeType", v.field, v.campus,
  'CAD 100', v.tuition, v.duration, v.intake,
  case v.entry_key
    when 'degree' then 'Ontario Secondary School Diploma or equivalent with the required Grade 12 subject prerequisites, including Grade 12 English and Mathematics. International Baccalaureate courses can satisfy Grade 12 requirements, and highly competitive degree programs may require a grade of 5 or higher. English proficiency for international applicants: IELTS Academic 6.5, TOEFL iBT 89, PTE 61, Duolingo 120, CAEL 60, or Cambridge C1 Advanced 175. Test results must be no more than two years old.'
    when 'grad' then 'A completed college diploma or university degree, evidenced by college or university transcripts showing graduation, plus a resume detailing relevant experience and a letter of intent stating the reason for applying. English proficiency for international applicants: IELTS Academic 6.5, TOEFL iBT 89, PTE 61, Duolingo 130, CAEL 60, or Cambridge C1 Advanced 175. Test results must be no more than two years old.'
    else 'Ontario Secondary School Diploma or equivalent, with secondary school transcripts showing proof of graduation, subjects taken and grades received. Grade 12 English and Mathematics credits are required. International Baccalaureate courses can satisfy Grade 12 requirements at a minimum grade of 4. English proficiency for international applicants: IELTS Academic 6.0, TOEFL iBT 79, PTE 58, Duolingo 110, CAEL 60, or Cambridge C1 Advanced 170. Test results must be no more than two years old.'
  end,
  v.learn_more_url, v.description, now(), now()
from (select id from public.universities where slug = 'georgian-college') as uni,
(values
  ('Addictions and Mental Health', 'addictions-mental-health-georgian', 'CERTIFICATE', 'Human Services', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/addictions-mental-health', 'Ontario College Graduate Certificate at Georgian College, program code ADMH, in the Human Services academic area. Delivered hybrid at the Barrie campus. Students develop the skill set to provide a client-centered and client driven continuum of treatment for individuals with addiction problems. With a strong framework of individual and group counselling skills, students study individual, gender, and societal considerations and the resulting treatment implications through the lens of trauma informed care. They practic e motivational interviewing techniques, cognitive behavioural therapy (CBT), and dialectal behaviour therapy (DBT) while learning to match client needs with intervention options. In addition, students reconstruct education and prevention strategies in an effort to design, facilitate and evaluate such tools. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Advanced Care Paramedic', 'advanced-care-paramedic-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/advanced-care-paramedic', 'Ontario College Graduate Certificate at Georgian College, program code PARM, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. Students acquire advanced knowledge and skills that prepare them to function as leaders in emergency situations, and practice out of hospital health care. Graduates demonstrate the ability to care for patients from diverse populations and to provide advanced medical treatment. Students experience classroom instruction, online learning, skills and patient simulation labs, as well as hospital, clinical, and field placements. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Advertising and Marketing Communications', 'advertising-marketing-communications-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/advertising-marketing-communications', 'Ontario College Diploma at Georgian College, program code ADMC, in the Business and Management academic area. Delivered in person at the Barrie campus. In this program, you explore the dynamic advertising and marketing communications industry. You gain knowledge in both theoretical and applied aspects of progressive marketing communications and acquire the industry techniques to perform the advertising/communications functions businesses require to compete in traditional and digital marketing environments. You study industry-focused courses, including social media marketing, media planning and buying, integrated marketing and communications, professional presentation skills, sales, graphic design, and digital video and content creation. Opportunities for work-integrated learning offer practical, hands-on experience with Treefort, Georgian''s in-house ad agency, where you apply knowledge and skills to develop client-based projects. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Anishnaabemowin and Program Development', 'anishnaabemowin-program-development-georgian', 'DIPLOMA', 'Indigenous Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/anishnaabemowin-program-development', 'Ontario College Diploma at Georgian College, program code ANPD, in the Indigenous Studies academic area. Delivered in-person and hybrid option at the Barrie campus. Students acquire Anishnaabemowin skills to develop and implement sustainable language programs in Indigenous communities and organizations. Students practice their speaking skills through interactions in the classroom, language immersion labs, community interactions, and through immersive Virtual Reality (VR) technology activities. The history of Anishnaabemowin and current issues affecting revitalization and preservation are also studied. Incorporating the Anishnaabe world-view, students examine the role and importance of Anishnaabemowin in ceremony, cultural values, and community. Exploring your study options? Consider Georgian''s one-year Maajii-Anishnaabemdaa (Start Speaking the Language) certificate program, starting fall 2023. Begin your foundational journey to speaking and understanding Anishnaabemowin and its relation to culture. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Architectural Technician', 'architectural-technician-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/architectural-technician', 'Ontario College Diploma, Co-op at Georgian College, program code ARTC, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. Students in this program prepare to assist architects, engineers, and other professionals connected to building projects. While developing skills in architectural design and gaining an understanding of the Ontario Building Code and construction technology, students take courses in computer-aided drafting and modeling and learn about sustainability and environmental subjects. This program is compatible with the first four semesters of the Architectural Technology program, and graduates may choose to continue into the third year of that program. If this doesn''t sound quite right for you, why not look into the Architectural Technology program ? It''s a three-year option that includes two co-op terms and specialized courses like Construction Materials, Site Planning, Contract Management, Project Costing and more. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Architectural Technology', 'architectural-technology-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/architectural-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code ARTE, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. Students in this program prepare for work with architects, engineers, project managers, and building officials as integral parts of teams that develop, present, execute, and review building projects. The program equips students with a comprehensive understanding of current competitive architectural and construction environments that challenge professionals in the field. The curriculum includes traditional and emerging construction technologies and materials, current codes and standards, sustainability and environmental subjects, and essential business and entrepreneurial strategies. Various aspects of architectural design are present throughout the curriculum, starting from design fundamentals and ending in the third year with a two-semester architecture capstone project evaluated by a large industry panel. Learning is supported by courses dedicated to industry-standard computer applications, such as Autodesk® AutoCAD® and Revit®, presented not only in printed drawings but also in renderings and interactive simulations using Chaos® Enscape®. The program also introduces students to leading-edge technologies related to Building Information Modeling (BIM), such as virtual reality immersion, 3D building scanning, and 3D printing. If this doesn''t sound quite right for you, why not take a look at the Architectural Technician program ? It''s a two-year option that gets you into the workforce faster and still provides substantial co-op opportunities. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Art and Design Fundamentals', 'art-design-fundamentals-georgian', 'CERTIFICATE', 'Design and Visual Arts', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/art-design-fundamentals', 'Ontario College Certificate at Georgian College, program code AADF, in the Design and Visual Arts academic area. Delivered hybrid at the Barrie campus. Creativity is essential for success in the 21st century. Through this program you acquire a solid foundation in art and design. Effective research, problem-solving, and conceptualization skills are combined with hands-on studio experience to learn new skills and techniques in both digital and traditional media. You develop a portfolio of your work, which is essential when applying to specialized art and design programs and positions in the creative field. Note: As a student in this program, you will not have courses in the summer term. Please review the program progression located in the program outline for more information. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Artificial Intelligence - Architecture, Design, and Implementation', 'artificial-intelligence-architecture-design-implementation-georgian', 'CERTIFICATE', 'Computer Studies', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September, January', 'grad', 'https://www.georgiancollege.ca/academics/programs/artificial-intelligence-architecture-design-implementation', 'Ontario College Graduate Certificate at Georgian College, program code AIDI, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. The Artificial Intelligence (AI) computing paradigm radically changes the functionality and capabilities of computer systems. This greatly increases the possibilities of what businesses can do with this exciting new technology and is causing disruption across all industry sectors. Artificial Intelligence systems can think, learn and take self-directed action in order to maximize the chance of successfully achieving a goal without having to be explicitly programmed or human intervention. This program provides students with the necessary background to become Artificial Intelligence (AI) system designers, programmers, implementers, or machine learning analysts. With a strong focus on applied skills, students learn how to design and implement supervised, unsupervised and reinforcement learning solutions for a variety of situations and solve AI challenges for a diverse set of industries. Advanced study in AI infrastructure, architecture, machine learning frameworks, reinforcement learning, neural networks, vision system, conversational AI and deep learning help students understand how to select, configure and apply the right technology tools to build the correct AI solution to solve a given challenge. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Artificial Intelligence Leadership and Management', 'artificial-intelligence-leadership-management-georgian', 'CERTIFICATE', 'Business and Management', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/artificial-intelligence-leadership-management', 'Ontario College Graduate Certificate at Georgian College, program code LIAI, in the Business and Management academic area. Delivered hybrid at the Barrie campus. Artificial intelligence (AI) has the extraordinary power to transform industry operations, customer experience, as well as product and service design. The opportunity to implement artificial intelligence cuts across every sector. Harnessing the potential of artificial intelligence for competitive performance requires a new type of professional. One who not only understands the capacity of the science, but has the expertise to apply it to organizational needs and strategies, and the leadership skills to navigate through the ethical, economic, and societal implications of artificial intelligence implementation. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Automotive Business', 'automotive-business-georgian', 'DIPLOMA', 'Automotive Business', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/automotive-business', 'Ontario College Diploma, Co-op at Georgian College, program code AUBU, in the Automotive Business academic area. Delivered hybrid at the Barrie campus. In this program, students are prepared for professional and essential support positions in the automotive industry by receiving a general business and specialized automotive education. Upon completion of the program, students have the skills, knowledge, and experience to build a career across a broad range of sectors in the automotive industry. Students have the opportunity to gain eight months of co-op work experience and are able to network with industry professionals to explore the various sectors within the industry. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Aviation Management', 'aviation-management-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/aviation-management', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code AVIA, in the Business and Management academic area. Delivered in person at the Barrie campus. This program is designed to give students knowledge and hands-on experience in aviation and management, as well as provide co-operative work experience in the aviation industry. Aviation courses focus on aircraft, airline and airport operations, aviation safety and security and flight systems and navigation. Students gain a solid understanding of the aviation industry in Canada and around the world. Management courses are designed to give students an understanding of business and management practices of marketing, human resource management, communications and project management to be prepared for future promotional opportunities. Students are given the opportunity to take the examination to receive their Restricted Aeronautical Radio Operation License. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Baking and Pastry Arts', 'baking-pastry-arts-georgian', 'CERTIFICATE', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/baking-pastry-arts', 'Ontario College Certificate at Georgian College, program code BAKE, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Launch your career as a baker or pastry chef to make a lot of dough! In this one-year certificate, the Baking and Pastry Arts program prepares you for a career as a baking professional. Through hands-on learning in bake labs, you examine the fundamentals of pastry making, study traditional and contemporary baking methods, and develop ''on-the-tool skills'' to produce delicious baked goods and desserts. Through classroom lectures, you learn baking theory, nutrition, trade calculations, sanitation, food safety, and business concepts to support the practical skills required in the daily operation of a bakery. As a graduate of this program, you are prepared to think critically, innovate, and apply business skills for lifelong career success as a baking professional across different sectors in the food service industry or as an entrepreneur and small business owner. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Big Data Analytics', 'big-data-analytics-georgian', 'CERTIFICATE', 'Computer Studies', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/big-data-analytics', 'Ontario College Graduate Certificate at Georgian College, program code BDAT, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. Big Data allows users to visualize past, present, and future patterns by linking and presenting information in meaningful ways. Data Analytics offers deeper insight into the meaning of data sets by telling the story behind the information. This enables stakeholders to make more informed decisions, predict trends and better understand the needs and sentiments of customers. This program provides students with a unique blend of theoretical knowledge and applied skills. Students learn how to collect, curate, manipulate, encode, and store data sets so they can be analyzed and mined in such a way that they can be reused and repurposed to solve present challenges as well as those that do not yet exist. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Biotechnology - Health', 'biotechnology-health-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, May', 'diploma', 'https://www.georgiancollege.ca/academics/programs/biotechnology-health', 'Ontario College Diploma at Georgian College, program code BIOT, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. Upon graduating from the Biotechnology – Health program, you are prepared for a career in biotechnology, a high-tech trade that spans many employment sectors. You develop technical and knowledge-based skills through comprehensive experiential learning, as you are exposed to a variety of experimental techniques using cutting-edge scientific equipment across disciplines including microbiology, molecular biology, tissue culture, biochemistry, analytical chemistry, and pharmaceutical biotechnology. Throughout the program, you explore current topics in the field and research potential biotechnology applications to address them. In accordance with accepted industry standards, you learn to collect, document, analyze, and present your lab and experimental data. Completion of a micro-credential in Changemaking and Social Entrepreneurism helps you to recognize opportunities in biotechnology and become serial problem solvers. Throughout the program, you are supported in the development of a living resumé as you expand your skillsets and create professional networks. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business', 'business-georgian', 'DIPLOMA', 'Business and Management', 'Barrie, Online', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business', 'Ontario College Diploma at Georgian College, program code BUSN, in the Business and Management academic area. Delivered hybrid at the Barrie, Online campus. Students acquire a foundational knowledge of the basics of business, with a focus on managing people and processes. Courses in economics, accounting, marketing, and human resources lay the groundwork for future careers and further studies. Students acquire skills in managing processes and people. Graduates can enter the workforce or continue studies as the program provides multiple pathways into degree and post-graduate diploma programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Accounting', 'business-accounting-georgian', 'DIPLOMA', 'Business and Management', 'Barrie, Online', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-accounting', 'Ontario College Diploma at Georgian College, program code BACN, in the Business and Management academic area. Delivered in person at the Barrie, Online campus. An accounting education helps you to understand "the numbers" which is critical to the success of every type of business. If you are a logical thinker and enjoy the challenge of unravelling the mystery of numbers then this program is for you. In this increasingly complex and competitive business environment, accounting skills are very much in demand. The program provides a foundation in all of the functional business areas and a comprehensive education in specific accounting practices and theory. Through a strong focus on application, students develop the skills needed for success in the business world; analytical thinking, problem solving, communication and teamwork. Students graduate ready to enter the workforce and support the accounting activities of any organization. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Accounting', 'business-accounting-co-op-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-accounting-co-op', 'Ontario College Diploma, Co-op at Georgian College, program code BACT, in the Business and Management academic area. Delivered in person at the Barrie campus. An accounting education helps you to understand "the numbers" which is critical to the success of every type of business. If you are a logical thinker and enjoy the challenge of unravelling the mystery of numbers then this program is for you. In this increasingly complex and competitive business environment, accounting skills are very much in demand. The program provides a foundation in all of the functional business areas and a comprehensive education in specific accounting practices and theory. Through a strong focus on application both in the classroom and through co-op work terms, students develop the skills needed for success in the business world; analytical thinking, problem solving, communication and teamwork. Students graduate ready to enter the workforce and support the accounting activities of any organization. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Agriculture', 'business-agriculture-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-agriculture', 'Ontario College Diploma, co-op at Georgian College, program code AGRI, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Agriculture is an increasingly complex industry, with sophisticated agribusiness managers required to make decisions about crop/herd selection and improvement, pest and soil management, farm safety, and agricultural production. In Georgian''s Business – Agriculture Diploma program, you explore both the business and science behind the industry. A combination of outdoor learning with time in classrooms and modern labs provides practical agricultural knowledge, as well as the business training necessary to successfully manage or provide services to agricultural businesses. This program connects you to the agribusiness industry and includes a co-operative work placement between first and second year, giving you hands-on experience and networking opportunities with others in the field. You''ll graduate with a competitive edge – with the ability to examine agricultural techniques through a business lens, and the skills to evaluate farm production methodologies, technologies and systems to inform financial and operational decisions. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Entrepreneurship', 'business-entrepreneurship-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-entrepreneurship', 'Ontario College Diploma at Georgian College, program code ENTB, in the Business and Management academic area. Delivered in person at the Barrie campus. This program is intended for students who wish to develop a strong educational and experiential base in business. Students develop skills in entrepreneurial thinking, market research, networking, financial literacy and planning, digital and traditional marketing, and human resource planning and management. Students explore intrapreneurship, social innovation, ideation and design thinking, as well as business principles and practices in order to successfully launch and operate a business. This program is particularly appropriate for students whose goal is to enter a family business, start their own business, enter employment in a small business, or become an intrapreneur within a large corporation. One of the key experiential outcomes is the research, development and presentation of a complete business plan for a new enterprise. Students will connect with industry and entrepreneurial mentors in the community and the College. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Entrepreneurship', 'business-entrepreneurship-co-op-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-entrepreneurship-co-op', 'Ontario College Diploma, Co-op at Georgian College, program code ENTC, in the Business and Management academic area. Delivered in person at the Barrie campus. This program is intended for students who wish to develop a strong educational and experiential base in business. Students develop skills in entrepreneurial thinking, market research, networking, financial literacy and planning, digital and traditional marketing, and human resource planning and management. Students explore intrapreneurship, social innovation, ideation and design thinking, as well as business principles and practices in order to successfully launch and operate a business. This program is particularly appropriate for students whose goal is to enter a family business, start their own business, enter employment in a small business, or become an intrapreneur within a large corporation. One of the key experiential outcomes is the research, development and presentation of a complete business plan for a new enterprise. Students will connect with industry and entrepreneurial mentors in the community and the College. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Marketing', 'business-marketing-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-marketing', 'Ontario College Diploma at Georgian College, program code BMKN, in the Business and Management academic area. Delivered in person at the Barrie campus. Marketing professionals drive organizational success for corporations and non-profits by translating customer desires into effective strategies. Students learn to assess market opportunities, segment target markets, and create strategies and tactics that help achieve organizational goals. Students build a solid business foundation and develop skills across the spectrum of marketing activity, from research, through strategy development and planning, sales, digital marketing and social media, and persuasive communication across media platforms. Through a busy, student-run agency, students work on a wide range of projects which they ultimately pitch to the clients for possible implementation. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Business - Marketing', 'business-marketing-co-op-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/business-marketing-co-op', 'Ontario College Diploma, Co-op at Georgian College, program code BMKT, in the Business and Management academic area. Delivered in person at the Barrie campus. Marketing professionals drive organizational success for corporations and non-profits by translating customer desires into effective strategies. Students learn to assess market opportunities, segment target markets, and create strategies and tactics that help achieve organizational goals. Students build a solid business foundation and develop skills across the spectrum of marketing activity, from research, through strategy development and planning, sales, digital marketing and social media, and persuasive communication across media platforms. Through a busy, student-run agency, students work on a wide range of projects which they ultimately pitch to the clients for possible implementation. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Cabinetmaking Techniques', 'cabinetmaking-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/cabinetmaking-techniques', 'Ontario College Certificate at Georgian College, program code CABT, in the Skilled Trades academic area. Delivered in person at the Barrie campus. In this project-based program, students are provided the opportunity to develop and advance foundational knowledge and skills for the cabinetmaking industry. Experiential learning ensures that students are competent in all aspects of the industrial cabinetmaking/woodworking field, from planning stages through to the application of final finishes on a variety of solids and manufactured products. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Carpentry and Renovation Techniques', 'carpentry-renovation-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Barrie, Owen Sound', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/carpentry-renovation-techniques', 'Ontario College Certificate at Georgian College, program code CRNT, in the Skilled Trades academic area. Delivered in person at the Barrie, Owen Sound campus. In this two-semester program you experience all facets of residential construction in an exciting hands-on environment. You learn trade-specific skills for employment in the construction and renovation sector. Through experiential learning you practice floor, wall and roof framing, demolition, renovations, stair construction, interior and exterior finish and sustainable construction techniques. Theory and applications of safety standards, building codes, blueprint reading, energy efficiency, and environmental stewardship practices are studied. You learn to interpret the Ontario Building Code as it applies to renovations and new construction. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Child and Youth Care', 'child-youth-care-georgian', 'DIPLOMA', 'Human Services', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/child-youth-care', 'Ontario College Advanced Diploma at Georgian College, program code CYCA, in the Human Services academic area. Delivered hybrid at the Barrie campus. Support children and youth who experience social, emotional, and behavioural needs that may be associated with mental health challenges, trauma and abuse, cognitive and developmental issues, and involvement with the child welfare and justice systems. Child and Youth Care practitioners assist children, youth, and their families in various settings to build on strengths and facilitate positive change while navigating challenges. Students explore, practice, and demonstrate a variety of evidence-informed therapeutic prevention and intervention strategies based on an understanding of risk and resiliency, relationship development, equity and inclusion, human development, family systems, and exceptionalities. The program offers hands-on interactive learning, community service initiatives, social innovation, and changemaking opportunities. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Civil Engineering Technician', 'civil-engineering-technician-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/civil-engineering-technician', 'Ontario College Diploma, Co-op at Georgian College, program code CVET, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. In this program you prepare to work with engineers and construction project managers as part of a team constructing roads, bridges, sewers, water mains, and other infrastructure. You determine data for cost estimation, perform materials testing, and assist in the administration of projects in the field. Teamwork and project-based learning are emphasized. This program is common with the first four semesters of the Civil Engineering Technology program, and graduates may choose to continue into the third year of that program. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Civil Engineering Technology', 'civil-engineering-technology-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/civil-engineering-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code CVTY, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. In this program you successfully prepare to join the rapidly evolving and growing industry of civil engineering. You are exposed to the construction and design of roads, bridges, sewers, watermains, and structures; are introduced to cost estimation; and experience field work, material testing, and project management. The application of codes and standards, site development techniques, and related computer technologies to integrated co-op placements prepares you to work with engineers, designers, and construction project managers as an integral part of the team. If this doesn''t sound quite right for you, maybe the Civil Engineering Technician program is! You can complete your studies in just two years and get into the workforce fast. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('College Foundations', 'college-foundations-georgian', 'CERTIFICATE', 'Liberal Arts', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/college-foundations', 'Ontario College Certificate at Georgian College, program code COLF, in the Liberal Arts academic area. Delivered in person at the Barrie campus. College Foundations is a one-year Ontario College Certificate designed for students seeking access to a broad range of college programs. As a student in this program, you can determine your academic goals and career pathways by selecting courses from a variety of vocationally specific programs. Additionally, you develop critical thinking skills and apply success strategies to support your academic and career development. As a student in this program, you gain skills and credits for transfer into further vocational post-secondary study or prepare to enter the workplace. This program is an excellent fit if you: Want to explore different fields before choosing a diploma or degree program. Prefer a personalized learning experience with one-on-one support. Want to earn transferable General Education credits while exploring your options. Appreciate a structured environment that provides both guidance and flexibility. Want to lighten your future workload by completing General Education courses in advance. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Communicative Disorders Assistant', 'communicative-disorders-assistant-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/communicative-disorders-assistant', 'Ontario College Graduate Certificate at Georgian College, program code CODA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. As a student in the CDA program, you gain knowledge and hands-on experience to work in an adjunctive capacity as supportive personnel to qualified Speech-Language Pathologists and/or Audiologists in a variety of treatment settings, including virtual care. Students focus on conducting programming after the Speech-Language Pathologist or the Audiologist has completed the assessment and determined the therapy plan. Students gain clinical experience in our on-site speech, hearing and language clinic and during the placement semester. Based on a thorough understanding of physiological and functional speech/language and hearing conditions, students develop programming skills and learn intervention techniques to elicit and sustain communication behaviours. In addition, students identify behaviour and environmental factors that can potentially support or erode the efficacy of therapy. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Community Crisis and Suicide Response', 'community-crisis-suicide-response-georgian', 'CERTIFICATE', 'Human Services', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/community-crisis-suicide-response', 'Ontario College Graduate Certificate at Georgian College, program code CCSR, in the Human Services academic area. Delivered hybrid at the Barrie campus. Canada''s first post-secondary program in community safety and wellbeing that specializes in community crisis and suicide response. Drawing on innovative and emerging community-led crisis models and public health strategies, students explore community-led approaches that elevate the standard of care in community crisis and suicide response. Using a trauma-informed, decolonial, and anti-oppressive framework, students gain knowledge and skills required to assess, intervene, and support individuals, families, and communities in crisis. Students are informed on culturally responsive approaches from authentic voices, particularly those from Black, racialized, Indigenous and 2SLGBTQIA+ communities. Students apply evidence-based strategies, and utilize experiential learning, including use of simulation to develop a comprehensive understanding of the complexities of community crisis and suicide response and how to navigate the mental health, addiction, and justice systems. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Community Integration Through Co-operative Education', 'community-integration-co-operative-education-georgian', 'CERTIFICATE', 'Liberal Arts', 'Barrie, Owen Sound', 'CAD 17,170 to 18,170/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/community-integration-co-operative-education', 'Ontario College Certificate at Georgian College, program code CICE, in the Liberal Arts academic area. Delivered in-person and hybrid option at the Barrie, Owen Sound campus. This program is designed for students with diverse learning challenges who require academic accommodations and modifications. Students enhance their academic and vocational knowledge and skills in both core and integrated courses, and practice this learning during field placements. Learning facilitators modify integrated courses to students'' specific strengths and abilities, and provide accommodations, tutor and support sessions to ensure the work is challenging and achievable. Students prepare for success in entry-level work, and build independence and self-advocacy skills for adult life. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Community and Justice Services', 'community-justice-services-georgian', 'DIPLOMA', 'Community Safety', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/community-justice-services', 'Ontario College Diploma at Georgian College, program code CJSR, in the Community Safety academic area. Delivered hybrid at the Barrie campus. Students gain the knowledge and skills required to work with at-risk and offender populations in a variety of institutional and community correctional programs that operate within and adjacent to the justice system. Our curriculum combines theory and a variety of applied, experiential and work integrated learning opportunities that allow students to graduate with job readiness skills. Students learn about industry-based subjects such as human rights, equity and inclusion, and advocacy; skills and abilities relating to interpersonal and professional communications; programming and interventions connected to client and case management, and the importance of mental health, wellness and resiliency. The program is delivered by faculty with industry expertise, and complemented by subject matter experts who share their knowledge as part of the course curriculum. Our program has a long-standing history of community partnerships that allow students to participate in community projects and unique experiential learning opportunities. In second year, students complete a 7-week immersive field placement at a community or custody based justice agency that supports graduates as they transition to the profession. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Computer Programming and Analysis', 'computer-programming-analysis-georgian', 'DIPLOMA', 'Computer Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/computer-programming-analysis', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code CMPA, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. In this program, students focus on computer programming, web development and leveraging data to help organizations make meaningful business decisions. Throughout the program, students learn how to write code using a variety of languages such as Arduino, ASP.NET, C#, C++, Java, JavaScript, PHP, SQL and Swift. Students gain experience developing software for diverse platforms including embedded systems, desktop, mobile, and mainframe systems. In addition, students are exposed to advanced concepts including systems analysis, Business Intelligence (BI), application security, data structures, and game and simulation programming. With a strong emphasis on business and entrepreneurial values, students gain experience in problem-solving, troubleshooting and systems building through a series of applied assignments, projects, and co-op work terms. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Computer Systems Technician - Networking', 'computer-systems-technician-networking-georgian', 'DIPLOMA', 'Computer Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/computer-systems-technician-networking', 'Ontario College Diploma, Co-op at Georgian College, program code CSTN, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. In this program, students focus on networking, operating systems, system administration, cloud computing, and security related to new computer networks and the maintenance of existing computer networks. As an official Cisco Networking Academy partner, certified instructors assist students preparing for industry-recognized certifications such as the Cisco Certified Network Associate (CCNA) Routing and Switching. Students gain experience in problem-solving, and effective oral and written communications through examination of current industry trends and requirements. Students acquire professional and entrepreneurial skills for industry and self-employment, as well as practical experience through participation in a co-op work term. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Construction Techniques', 'construction-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/construction-techniques', 'Ontario College Certificate at Georgian College, program code COTE, in the Skilled Trades academic area. Delivered in person at the Barrie campus. In this program, students develop hands-on skills and gain experience in a variety of construction-related skilled trades. Using project-based learning techniques, students focus on applying the basics of entrepreneurship and sustainability within the construction industry. Students are introduced to a variety of construction focused courses including carpentry, cabinetry, plumbing, electrical techniques, small engine mechanics, drafting and heating and cooling. In addition, students prepare to make informed decisions related to the next steps in their education and careers. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Culinary Management', 'culinary-management-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/culinary-management', 'Ontario College Diploma, Co-op at Georgian College, program code CULN, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Touch, taste and feel the difference! Working with locally grown and gathered ingredients from Turtle Island, also known as North America, you will experience unrivaled hands-on learning to prepare for employment in multiple sectors of the food service industry. You develop job-ready skills and acquire knowledge to learn the business of kitchen operations, integral for success, as a culinary professional to work in the world''s best kitchens. The program focuses on ingredient identification, product knowledge, cooking skills and techniques, menu writing, and contemporary artisanal food production to deliver, a ''food of place'', cultural experience. The culmination of coursework and experiential learning positions you for the Capstone Project to showcase your culinary and professional leadership skills. Through this program, students complete a paid coop placement and the in-school portion of the cook apprenticeship program of the Ministry of Labour, Immigration, Training, and Skills Development. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Culinary Skills', 'culinary-skills-georgian', 'CERTIFICATE', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/culinary-skills', 'Ontario College Certificate at Georgian College, program code CULI, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Cooking for success! You will learn how to work in professional kitchens through the development of fundamental culinary knowledge, food preparation and artistic presentation skills that prepares you for lifelong career success with strong industry connections. Our Culinary Skills program has the highest hours in practical training aligned with Level 1 and Level 2 Cook Apprenticeship, meeting the requirements from the Ministry of Labour, Immigration, Training and Skills Development. You reliably demonstrate professionalism, culinary techniques, business management skills, product knowledge and identification, while applying classical and contemporary skills in an unmatched, hands-on learning environment. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Cybersecurity', 'cybersecurity-georgian', 'CERTIFICATE', 'Computer Studies', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'January', 'grad', 'https://www.georgiancollege.ca/academics/programs/cybersecurity', 'Ontario College Graduate Certificate at Georgian College, program code CYBE, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. You prepare for careers involving the development, evaluation, and support of cybersecurity solutions. Building on previous educational and industry experiences, you learn to create cost-effective and secure computing environments. You develop the knowledge and skills to categorize, design, implement and integrate technical safeguards to ensure the security of information systems. Emphasis is placed on cultivating the interpersonal, organizational, technical, communication, and problem-solving skills applied to enhance the effective implementation of security in a business environment. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Dental Assisting (Levels I and II)', 'dental-assisting-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/dental-assisting', 'Ontario College Certificate at Georgian College, program code DNAS, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. You prepare for a position as a Certified Dental Assistant (Level I and II) by focusing on professional standards. You have opportunities with a variety of practical experiences such as placements in the Georgian College Oral Health Clinic and in the community, including clinical and specialty practice, education, health promotion, and office administration. In addition to clinical skills, you develop hands on experience with dental materials including appliance fabrication. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Dental Hygiene', 'dental-hygiene-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/dental-hygiene', 'Ontario College Advanced Diploma at Georgian College, program code DNTH, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. You prepare for the role of oral health professional specializing in health promotion, disease prevention, and therapeutic care. The curriculum encompasses dental hygiene theory and practice, oral health and biomedical sciences, and the practical skills required for clinical practice, including hands-on learning labs and clinical experiences. You learn the principles of professional responsibility and communication, health promotion, advocacy and evidence-informed health care through the lens of equity, diversity and inclusion principles. You begin by applying theory to practice starting in a preclinical setting, gradually building the competence to apply skills in a client-care environment. Under supervision, you are supported while you provide ethical and culturally sensitive dental hygiene care onsite in the Georgian College Oral Health Clinic and in community placements. This program is highly competitive. Learn about admission requirements for highly competitive programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Denture Design and Fabrication', 'denture-design-fabrication-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/denture-design-fabrication', 'Ontario College Diploma at Georgian College, program code DDFA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. In a dental laboratory environment, you develop skills in design and fabrication of dentures including complete and partial prosthetics and implants. You use a problem-solving framework basing all decisions, judgments and interventions on current theory and research. An emphasis is placed on interprofessional education and learning to work within a collaborative oral health-care team. You employ technologies to design and fabricate digital dentures with the help of computer-aided design (CAD) and computer-aided manufacturing (CAM) software, scanners, 3D printers, and bench mills. Legal and ethical responsibilities are stressed. In preparation for employment, you practice and enhance your knowledge and skills of denture design and fabrication procedures in an external professional laboratory. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Denturism', 'denturism-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/denturism', 'Ontario College Advanced Diploma at Georgian College, program code DNTM, in the Health, Wellness and Sciences academic area. Delivered hybrid at the Barrie campus. As a regulated health care professional, you develop knowledge consistent with a denturist''s scope of practice, in particular assisting clients in achieving a beautiful smile. As a student Denturist, you use a problem-solving framework basing all decisions, judgments and interventions on current theory and research. An emphasis is placed on interprofessional education, learning to work within a collaborative oral health-care team, and training in clinical aspects related to your new field of study, including complete and partial prosthetics, immediate dentures, and implants. You employ technologies to design and fabricate digital dentures with the help of design software, scanners, printers and mills. Legal and ethical responsibilities, with an understanding of business practices related to self-employment are stressed and an important part of becoming an independent health care practitioner. East Coast Canada intake opportunity Georgian College is proud to offer an intake in Halifax for its accredited Denturism program. Available only to domestic students residing in Atlantic Canada, this intake offers the same recognized credential as the Barrie Campus, meeting the standards of the College of Denturists of Ontario. Courses will be delivered through a combination of remote learning (online), and in-person labs in Halifax. Interested students can apply through OCAS to the Denturism (online, Halifax cohort) (DNTM). For more details, please review the International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Developmental Services Worker', 'developmental-services-worker-georgian', 'DIPLOMA', 'Human Services', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/developmental-services-worker', 'Ontario College Diploma at Georgian College, program code DSWR, in the Human Services academic area. Delivered hybrid at the Barrie campus. Students develop the knowledge and skills to support children, youth and adults who have a developmental disability in all aspects of life across the lifespan. Respecting an individual''s right to direct their life, students develop advocacy skills that promote self-determination and assist individuals in the development of skills that encourage independence, community engagement, and citizenship. In the counselling and apartment labs, students practice sign language, medication administration, health care skills, counselling supports, and use of assistive devices and technology. In collaboration with community partners, students plan and implement activities that promote inclusion and self-determination. Other areas of study include intellectual, physical and mental disabilities, autism and fetal alcohol spectrum disorders, support options, health and well-being, social relationships, and teaching strategies. Students consolidate this learning in fourteen weeks of supervised field placements in their preferred geographical location. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Diagnostic Medical Sonography', 'diagnostic-medical-sonography-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/diagnostic-medical-sonography', 'Ontario College Advanced Diploma at Georgian College, program code SONO, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. Imagine yourself as a compassionate professional and a vital member of a cutting-edge healthcare field. The Diagnostic Medical Sonography program equips you with the knowledge, skills, and experience needed to excel in this rapidly advancing industry. Also known as ultrasound, diagnostic medical sonography utilizes high-frequency sound waves to assess the developing fetus, abdomen, pelvis, and blood vessels. Every patient presents unique needs, and as a student, you develop diagnostic problem-solving abilities and teamwork skills to provide exceptional care. Guided by experienced faculty, you build a strong foundation in anatomy, physiology, pathology, and quality sonographic imaging. Hands-on training in simulation labs prepares you for clinical placements in diverse healthcare settings. T hroughout the program, emphasis is placed on interprofessional collaboration, patient safety, effective communication, and high sta ndards of pati ent care, ensuring you are well-prepared to succeed as a Diagnostic Medical Sonographer. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Digital Content Creation and Strategy', 'digital-content-creation-strategy-georgian', 'CERTIFICATE', 'Design and Visual Arts', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/digital-content-creation-strategy', 'Ontario College Graduate Certificate at Georgian College, program code DGCC, in the Design and Visual Arts academic area. Delivered in-person and hybrid option at the Barrie campus. Post-Graduate Work Permit Eligible (PGWP) Digital Content Creation and Strategy prepares you to capture ideas and deliver effective messages in today''s media-rich business environment. Through a combination of practical and theory-based learning methods, you develop skills in the production and management of social media, communications, video and audio production, photography, and web design. Focusing on user experience and design functionality, you gain and develop skills through a combination of independent and collaborative projects applied in the context of content creation, strategy and curation. Ultimately, such skills can be applied to almost any sector that informs, engages or educates an audience. #yourvibeyourstory (LinkedIn) International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Electrical Engineering Technician', 'electrical-engineering-technician-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/electrical-engineering-technician', 'Ontario College Diploma, Co-op at Georgian College, program code EETN, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. Students are provided with the theoretical knowledge and technical skills to enter the electrical workforce. Classroom learning is combined with extensive hands-on experience in well-equipped, modern labs. Students are introduced to power transmission and distribution and robotics as well as maintenance and troubleshooting techniques for industry, with a strong focus on health and safety. Computer aided drafting, electronic and digital circuits, microprocessors, programming and programmable logic controllers are also studied. Students gain valuable experience during a co-op work term, while developing industry contacts for possible post-graduation employment opportunities. If this doesn''t sound quite right for you, the Electrical Engineering Technology program might be more up your alley. It includes extra co-op time and advanced courses like Power Quality and Distribution, Advanced Programmable Logic Controllers and Electrical Protection and Control. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Electrical Engineering Technology', 'electrical-engineering-technology-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/electrical-engineering-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code EETY, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. This Ontario Association of Certified Engineering Technicians and Technologists (OACETT) accredited program, offers students advanced courses in electrical power systems, robotics, programmable logic controllers, networking, instrumentation and project management. Students gain hands-on experience in associated lab classes using state of the art hardware and test equipment. These courses, together with experience gained in three coop work terms with industry partners, provide students with a broad technical background and a wide range of employment opportunities in the electrical industry. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Electrical Techniques', 'electrical-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Midland, Owen Sound', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/electrical-techniques', 'Ontario College Certificate at Georgian College, program code ELTQ, in the Skilled Trades academic area. Delivered in person at the Midland, Owen Sound campus. Students are introduced to the theoretical and practical aspects of the electrical industry so they can perform most basic electrical techniques under the supervision of a qualified person. Upon completion of the program, students can apply for work as an electrical apprentice, or they may choose to continue their education and apply for an Electrical Engineering Technician or Technologist post-secondary program. Students study health and safety, applied math, entrepreneurship, electrical and electronic theory. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Electromechanical Engineering Technician - Mechatronics', 'electromechanical-engineering-technician-mechatronics-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/electromechanical-engineering-technician-mechatronics', 'Ontario College Diploma, co-op at Georgian College, program code METT, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. The Electromechanical Engineering Technician two-year diploma is a comprehensive program designed to equip you with the relevant practical skills and theoretical knowledge to be successful in the field of electromechanical engineering. Program courses integrate aspects of electrical, mechanical, and computer engineering to provide a balanced curriculum that prepares you for a wide range of technical roles across industries within manufacturing, automation, robotics, instrumentation, hydraulics, pneumatics, industrial maintenance, and fabrication. The program curriculum emphasizes a balance between applied, hands-on learning and classroom theory in our well-equipped and modern labs, including opportunities to develop in-demand skills such as computer-aided design (CAD) and computer-aided manufacturing (CAM). Your learning is combined with workplace experience through a four-month co-op work term that connects you to industry contacts and develops networks for future employment. On completion of the program, you may also choose to continue your studies in the third year of the Electromechanical Engineering Technology – Mechatronics program. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Electromechanical Engineering Technology - Mechatronics', 'electromechanical-engineering-technology-mechatronics-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/electromechanical-engineering-technology-mechatronics', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code METR, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. As we enter the next industrial revolution, advanced technology demands interdisciplinary skills. Mechatronics is the interdisciplinary study of electrical, mechanical and computing systems. Students gain expertise in electrical, mechanical, and computer engineering, and explore how these disciplines are interconnected. Using the systems level approach, students develop both the applied skills and theoretical knowledge to build, troubleshoot and support next generation industrial systems. Students acquire an understanding of electronics, digital circuits, motor control, robotics, programmable logic controllers (PLCs), pneumatics, hydraulic systems, machining, dynamics, stress analysis, the internet of things, web and database systems, and interface programming. Through an official partnership with Siemens, students prepare for industry recognized certifications including the Siemens Mechatronics Systems Certification program (SMSCP) certification. Students gain experience in problem solving, and effective oral and written communications through examination of current industry trends and requirements. Co-op terms provide opportunities to experience real-life industry skills, networking, and potential career paths. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Environmental Technician', 'environmental-technician-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/environmental-technician', 'Ontario College Diploma, Co-op at Georgian College, program code ENTN, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. In the Environmental Technician program, you gain the experience and skills required to enter the workforce as an entry-level practitioner who has the ability to use environmental sampling, monitoring and testing equipment, and information technology tools. You become familiar with standard operating procedures for conducting environmental projects. As you progress through this program, you build applied knowledge of health, safety, and environmental legislative requirements, environmental management systems, and the basic principles of ecosystem-based management for sustainability. With a focus on experiential learning, you gain hands-on experience through fieldwork opportunities and prepare for entry into a range of positions as you undertake industry-related certifications. If this doesn''t sound quite right for you, why not look into the Environmental Technology program ? It''s a three-year option that includes three co-op terms and specialized courses like Atmospheric Science, Sustainable Technologies, Toxicology and Contaminants in Organisms and more. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Environmental Technology', 'environmental-technology-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/environmental-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code ENVR, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. In this program, you gain the advanced skills required to enter the workforce as an environmental practitioner with the ability to use environmental sampling, monitoring and testing equipment, as well as information technology tools. You gain experience in preparing and interpreting data using various analytical methods. You become familiar with the principles of ecosystem-based management for sustainability and develop the ability to manage environmental projects from planning through to implementation and maintenance. Through applied knowledge of health, safety and environmental requirements, you are able to contribute to risk assessment and environmental systems management. The experience and knowledge you gain focuses on the need for designing and implementing systems to prevent, control and clean-up environmental contaminants. You are provided an opportunity to apply your skills through partnerships in the community, and you gain hands-on experience through field work opportunities and prepare for entry into a range of positions as you undertake industry-related certifications. If this doesn''t sound quite right for you, why not take a look at the Environmental Technician program ? It''s a two-year option that gets you into the workforce faster and still provides substantial co-op opportunities. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Esthetician - Spa Management', 'esthetician-spa-management-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/esthetician-spa-management', 'Ontario College Diploma at Georgian College, program code ESPA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. The Esthetician – Spa Management program provides you with the practical skills, business training and professional competencies required to work in the growing field of esthetics. Taught by diverse faculty with extensive industry experience, this internationally recognized curriculum offers a holistic approach to teaching spa modalities, including specialized skin, body and hand/foot treatments; corrective make up techniques; and nutritional concepts for skin and body health. With over 240 hours of hands-on experience in Georgian''s Spa clinic, you hone your practice and develop the professional ethics and skills required to run a small business. You also gain the academic preparation for international testing. As a graduate, you''ll have an inspired passion for health and wellness, as well as the technical and management skills necessary for a successful and rewarding career in the esthetics industry. IMPORTANT: The Esthetician program has a strict "no jewellery" policy and uniform requirement for all labs and clinics. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Fitness and Health Promotion', 'fitness-health-promotion-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/fitness-health-promotion', 'Ontario College Diploma at Georgian College, program code FHPR, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Do you have a passion for exercise and physical activity? Are you inherently interested in how exercise and dietary strategies can enhan ce health and performance? The program starts with the fundamentals of the fitness and health promotion field such as anatomy, physiology, biomechanics, client counselling, and nutrition. These courses are combined with a large number of practical based learning hours in dedicated exercise science labs. You gain industry experience through preparation of healthy foods in culinary labs, planning and executing a health promotion event, the opportunity to train clients on campus, and off-campus work-integrated learning. G raduates receive credit for their college c ourses and can proceed to formal articulations in various university degree programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Flight Services - Cabin Management', 'flight-services-cabin-management-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/flight-services-cabin-management', 'Ontario College Diploma, Co-op at Georgian College, program code FSCM, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Flight Attendants are ambassadors of the passenger experience, playing a critical role in ensuring safety and service in the airline industry. The Flight Services-Cabin Management diploma program develops the essential skills, knowledge, and professional behaviours required for this dynamic career. Students gain hands-on experience and theoretical knowledge in passenger safety, emergency preparedness, and in-flight service. Emphasis is placed on regulatory compliance, the use of emergency equipment, and leadership in managing diverse passenger interactions. Students build the confidence to handle real-world scenarios while fostering a service-driven mindset and cultural awareness. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Food and Nutrition Management', 'food-nutrition-management-georgian', 'CERTIFICATE', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September, January', 'grad', 'https://www.georgiancollege.ca/academics/programs/food-nutrition-management', 'Ontario College Graduate Certificate at Georgian College, program code FDNM, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. If you have a passion for healthcare and nutrition then the Food and Nutrition Management program at Georgian College may be your recipe for success. Through hands-on, experiential learning in lab and industry settings, students gain the ability to take their career to the next level in a rapidly expanding, global industry. With a focus on health and nutrition alongside the acquisition of effective management strategies, students sharpen the skills they need to remain current within the dynamic and evolving healthcare and nutrition industry. Built-in work placements expose students to the industry and help them connect with future employers. Accredited by the Canadian Society of Nutritional Managers. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Game - Design and Simulation', 'game-design-simulation-georgian', 'DIPLOMA', 'Computer Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/game-design-simulation', 'Ontario College Diploma at Georgian College, program code GAME, in the Computer Studies academic area. Delivered in person at the Barrie campus. In the Game – Design and Simulation program, you''ll gain a strong foundation in game programming, design, and simulation while preparing to create interactive digital experiences. As you develop your technical problem-solving skills, you''ll learn to design games and simulations across various platforms. Through hands-on projects, you''ll gain experience in game mechanics, real-time rendering, artificial intelligence, and multiplayer systems. The curriculum is designed to guide your learning, starting with fundamental concepts in game art, design, and programming as you build your first interactive projects, then progressing to more advanced topics like artificial intelligence, multiplayer design, and immersive technologies. You''ll have the opportunity to create a full 3D game that incorporates simulations and virtual reality. You gain the essential skills that aid the game development process, including project management and production workflows, which will help you develop teamwork and problem-solving abilities through long-term group projects. By graduation, you''ll have a strong portfolio of projects and the technical expertise needed for careers in game development, simulation engineering, and the interactive software industry. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Game - Development', 'game-development-georgian', 'DIPLOMA', 'Computer Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/game-development', 'Ontario College Advanced Diploma at Georgian College, program code GAMD, in the Computer Studies academic area. Delivered in person at the Barrie campus. The field of game development is all about breathing life into digital worlds. It combines creative, technical, and artistic skills to craft interactive environments for players. Game developers create unique gaming realms by integrating levels, characters, assets, props, and systems for various platforms, including computers, consoles and mobile devices. In the Game – Development program, you will embark on a journey from concept to reality, transforming game ideas and simulation concepts into compelling experiences. You learn to develop narratives, create and manage 2D and 3D digital assets, and master techniques in lighting and rendering, game artificial intelligence, and multiplayer networking. Additionally, you explore the development of serious games and emerging technologies, ensuring that, as a graduate, you are at the forefront of innovation and capable of creating immersive and visually stunning game worlds. Through hands-on experience with cutting-edge game engines and design tools, you gain practical skills in game mechanics and dynamics. These skills are not limited to gaming; they can also be applied to developing simulations for industries such as architecture, engineering, healthcare, manufacturing, and education and training. By the end of the program, you are well-prepared to enter the gaming industry or explore diverse career opportunities in various fields. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Gas Technician', 'gas-technician-georgian', 'CERTIFICATE', 'Skilled Trades', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/gas-technician', 'Ontario College Certificate at Georgian College, program code GAST, in the Skilled Trades academic area. Delivered in person at the Barrie campus. In this program, students develop the theoretical and practical skills required to obtain the Technical Standards and Safety Authority (TSSA) Gas Technician 3 (G.3) and Gas Technician 2 (G.2) certifications. Students study workplace safety, codes/regulations, propane fundamentals, system testing and troubleshooting in order to maintain and install gas-fired equipment in residential and commercial settings. The Barrie Campus program is delivered evenings and weekends only. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('General Arts and Science - English for Academic Purposes', 'general-arts-science-english-academic-purposes-georgian', 'CERTIFICATE', 'Liberal Arts', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/general-arts-science-english-academic-purposes', 'Ontario College Certificate at Georgian College, program code EAPC, in the Liberal Arts academic area. Delivered in-person and hybrid option at the Barrie campus. This program helps you learn or improve your English, and prepares you for post-secondary study and future employment. Y ou develop English proficiency in the areas of reading, writing, speaking, listening, grammar, and vocabulary, while also focusing on essential skills for success and communication in various academic and professional contexts. Language learning is facilitated through interactive activities, discussions, use of multimedia materials, in-class instruction and experiential learning outside the classroom, as well as an exploration of personal, abstract and global topics. Levels 1 and 2 of General English as a Second Language (ESLG) are also available. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('General Arts and Science - Shki Miikan (New Road)', 'general-arts-science-shki-miikan-new-road-georgian', 'CERTIFICATE', 'Indigenous Studies', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/general-arts-science-shki-miikan-new-road', 'Ontario College Certificate at Georgian College, program code GASK, in the Indigenous Studies academic area. Delivered in person at the Barrie campus. During this foundation year, students embark on a personal journey of discovery. Students develop a solid academic base, assess education and career options, and develop self-management skills. Through Indigenous language and teachings, students explore their sense of cultural identity. Traditional teachings and smudging are integrated daily throughout each academic semester in social activities, individual program courses, and Traditional Teacher/Elder visits. Please note: Indigenous includes First Nations, Métis, Inuit, and Non Status People. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Golf Industry Management', 'golf-industry-management-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/golf-industry-management', 'Ontario College Diploma at Georgian College, program code GLFI, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. This program is designed to prepare students for exciting employment opportunities in the $15 billion Canadian golf industry, both on the golf course and off. Theoretical concepts taught in the classroom are blended with practical learning opportunities gained through exposure to various golf facilities. At the golf course level, students examine the many aspects of golf operations such as agronomy, hospitality, retail and golf event planning. Away from the golf course, students have the opportunity to explore a variety of career paths at facilities that support the game. Students gain professional and managerial skills for industry and self-employment, as well as practical experience through participation in a work term and extensive field trips to golf courses and golf industry properties. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Graphic Design', 'graphic-design-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/graphic-design', 'Ontario College Advanced Diploma at Georgian College, program code GRDE, in the Design and Visual Arts academic area. Delivered in person at the Barrie campus. This program is designed provide students with an education in the principles and practices of visual communication design. Students learn the skills and knowledge necessary to create effective designs for a wide range of both traditional and digital applications, including branding, editorial, advertising, information design, user interfaces, web and social media, and motion graphics. Throughout the program, students explore a variety of design topics, including layout, typography, composition, colour theory, and production. They develop skills in industry-standard software and tools while working in a hands-on, project-based learning environment. The depth and breadth of instruction in design and technology is reflected in the portfolio developed in this three-year program, preparing students to take on more creative and independent roles once they enter the workplace. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Graphic Design Production', 'graphic-design-production-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/graphic-design-production', 'Ontario College Diploma at Georgian College, program code GRDP, in the Design and Visual Arts academic area. Delivered in person at the Barrie campus. This program is designed to provide students with an education in the principles and practices of visual communication design. Students learn the skills and knowledge necessary to create effective designs for a wide range of both traditional and digital applications, including branding, editorial, advertising, information design, user interfaces, web and social media, and motion graphics. Throughout the program, students explore a variety of design topics, including layout, typography, composition, colour theory, and production. They develop skills in industry-standard software and tools while working in a hands-on, project-based learning environment. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Hairstyling', 'hairstyling-georgian', 'DIPLOMA', 'Skilled Trades', 'Barrie, Barrie Downtown', 'CAD 16,990 to 29,200/year', 1.0, 'September, January, May', 'diploma', 'https://www.georgiancollege.ca/academics/programs/hairstyling', 'Ontario College Diploma at Georgian College, program code HAIR, in the Skilled Trades academic area. Delivered in-person and hybrid option at the Barrie, Barrie Downtown campus. This program covers all the skills required to work in the Hairstyling trade. Offered in a condensed 3-semester format, students complete the diploma in one year through progressive levels of theory and practical techniques. Students are introduced to relevant legislation in the trade, health and safety issues, professional ethics, communication skills, and entrepreneurial practices, including preparation for entering into the workforce. The program focuses on hands-on training in hair cutting and styling, hair design, as well as colouring and lightening, permanent wave, and hair additions. Students also take a specialized course in relaxing/smoothing, colouring, cutting, and styling different hair textures. Interested in an apprenticeship? Georgian also offers a Hairstylist apprenticeship program. Visit the apprenticeships page to learn more and find out how to apply. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Health Informatics', 'health-informatics-georgian', 'CERTIFICATE', 'Business and Management', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/health-informatics', 'Ontario College Graduate Certificate at Georgian College, program code HINF, in the Business and Management academic area. Delivered hybrid at the Barrie campus. Georgian College''s Health Informatics program will equip you with the skills needed to thrive in the quickly evolving digital health world. You will gain skills and knowledge in the areas of healthcare delivery, information technology, and data analysis. You will explore clinical informatics, health information management, privacy and security, healthcare systems and information technology. Throughout your program you will gain hands-on learning by immersing yourself in case-studies and projects that address the complexities of emerging technologies in our healthcare system. In the second semester you will complete your capstone course by working through an industry project, exposing you to the steps of business analysis and change management in a real-world scenario. Upon graduation, you will have the competencies and professional skills required to be successful in the health informatics field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Heating, Refrigeration and Air Conditioning Technician', 'heating-refrigeration-air-conditioning-technician-georgian', 'DIPLOMA', 'Skilled Trades', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/heating-refrigeration-air-conditioning-technician', 'Ontario College Diploma, Co-op at Georgian College, program code HRAC, in the Skilled Trades academic area. Delivered in person at the Barrie campus. In the Heating, Refrigeration, and Air Conditioning Technician program (HRAC), students gain the required skills to install, service, and maintain the environmental systems for residential and commercial buildings, including working with a variety of gas appliances, as well as an introduction to refrigeration and air conditioning. Students examine energy-efficient and environmentally friendly approaches and read, utilize, and produce Heating, Refrigeration, and Air Conditioning (HRAC) drawings using industry standard software. Students gain the required skills to obtain the Technical Standards and Safety Authority (TSSA) Gas Technician 2 (G.2) exams to become a licensed gas technician. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Business Administration (Automotive Management)', 'honours-bachelor-business-administration-automotive-management-georgian', 'BACHELOR', 'Automotive Business', 'Barrie', 'CAD 20,360 to 20,450/year', 4.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-business-administration-automotive-management', 'Honours Bachelor Degree at Georgian College, program code BBAA, in the Automotive Business academic area. Delivered in person at the Barrie campus. This program combines a degree-level business education with experiential knowledge focused on the automotive industry. In preparation for a landscape that is constantly evolving and to identify and respond proactively to these changes, students analyze current issues, trends and developing technologies relevant to the automotive industry. Through a variety of delivery methods including lectures, discussions, case-studies, problem-solving and special projects in collaboration with industry and industry stakeholders, students are challenged to critically examine, evaluate and present complex information in support of sound management decision-making. Work integrated learning is achieved through a series of co-operative education work terms, serving to maximize the link between theory and practice, and to foster mutually beneficial business relationships between the student and industry partners. This program includes experiential learning through participation in a major, automotive focused exposition that requires students to work collaboratively and interactively with industry and industry partners in developing their communication and leadership skills, and increasing their professionalism. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Counselling Psychology', 'honours-bachelor-counselling-psychology-georgian', 'BACHELOR', 'Human Services', 'Barrie', 'CAD 20,360 to 20,450/year', 4.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-counselling-psychology', 'Honours Bachelor Degree at Georgian College, program code HBCP, in the Human Services academic area. Delivered in person at the Barrie campus. This program is designed for students who want to understand human behaviour and use this knowledge to promote the mental health of individuals, families, groups, and communities. Students are exposed to a range of counselling approaches as well as a strong foundation in psychology research and theory. In the internship and intraternships, students obtain experience with different populations and working environments, which allows them to explore career options and practice the skills that prepare them for employment or graduate studies. The curriculum fosters an understanding of diverse sociocultural factors, lifespan development, theory and practice in a range of counselling approaches, ethical and evidence-based professional practices, as well as the research methods, and psychological theories that inform counselling practice. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Interior Design', 'honours-bachelor-interior-design-georgian', 'BACHELOR', 'Design and Visual Arts', 'Barrie', 'CAD 20,360 to 20,450/year', 4.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-interior-design', 'Honours Bachelor Degree at Georgian College, program code BAID, in the Design and Visual Arts academic area. Delivered in person at the Barrie campus. Express your creativity and become a leader in the growing field of interior design. At Georgian College, we value the potential of our students and provide an innovative and collaborative learning experience with a focus on hands-on learning. Access to current digital technology, and a four-month Co-op semester offer exceptional job preparation that is well recognized by the professional community. Students in this program work closely with faculty who have extensive industry experience in a studio environment similar to a professional design office. You are challenged to rethink the built environment by advocating positive change in a rapidly evolving global context. Explore and design sustainable interior environments that support and enhance human health, safety, well-being, performance, and experience. At Georgian, you construct sophisticated interior designs and document construction drawings and specifications to communicate concept development and design resolution and to celebrate creative vision. Founded on the broader aspects of evidence-based research, professional practice, and design integrity, this ARIDO recognized bachelor''s degree program provides opportunities to explore your personal expression and establishes you as an innovator in the field of interior design. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Police Studies', 'honours-bachelor-police-studies-georgian', 'BACHELOR', 'Community Safety', 'Barrie', 'CAD 20,360 to 20,450/year', 4.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-police-studies', 'Honours Bachelor Degree at Georgian College, program code BAPS, in the Community Safety academic area. Delivered hybrid at the Barrie campus. In this unique Honours Bachelor of Police Studies program, students experience hands-on engagement in such areas as forensics, cold case investigations, criminology, criminal behaviour analysis, geographic profiling and cybercrime. Students explore a broad range of themes related to policing, criminal justice, issues of diversity, professionalism, leadership, and scholarship. Approaching problems from a variety of perspectives supports critical thinking, sound decision-making, and innovation. Network building and connections with potential employers are provided by our strong partnerships with municipal, provincial, and federal police services and other criminal and civil justice-related agencies. These connections also provide valuable opportunities for a variety of field experiences through the fourteen-week co-op. Graduates are prepared for a variety of careers in the justice field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Science - Nursing', 'honours-bachelor-science-nursing-bscn-georgian', 'BACHELOR', 'Health, Wellness and Sciences', 'Barrie, Owen Sound', 'CAD 20,360 to 20,450/year', 4.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-science-nursing-bscn', 'Honours Bachelor Degree at Georgian College, program code HBSN, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie, Owen Sound campus. This program prepares graduates for a life-long career as a Registered Nurse. Grounded in a vibrant urban and rural community, faculty work collaboratively with practice partners to provide diverse experiences for students to learn about the complexity of nursing in a modern healthcare environment. The role of nurses as leaders in healthcare delivery is taught from a practice-based framework where real life experiences are a focus of teaching and learning. Faculty and preceptors actively work with students to create opportunities for scholarship and professional growth which support the development of nurses who can serve as leaders and advocates for person-centered care. Graduates from this program obtain the additional designation of RN Prescriber. Georgian College is authorized by the College of Nurses of Ontario to provide RN Prescriber education. Your Honours BScN nursing degree from Georgian will open doors to careers in hospitals, long-term care, clinics or community health services. This community-based program reflects the specific health needs of local populations, including the elderly, Indigenous and Francophone peoples, as well as those with mental health challenges. This program has been approved by the College of Nurses of Ontario (CNO) as a full-time, direct-entry program for individuals with no previous nursing knowledge. Those with previous nursing credentials should check out Georgian''s International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Honours Bachelor of Science – Nursing RPN to BScN Advanced Standing Pathway (Bridge)', 'honours-bachelor-science-nursing-bridge-georgian', 'BACHELOR', 'Health, Wellness and Sciences', 'Barrie, Orangeville, Owen Sound', 'CAD 20,360 to 20,450/year', 3.0, 'September', 'degree', 'https://www.georgiancollege.ca/academics/programs/honours-bachelor-science-nursing-bridge', 'Honours Bachelor Degree at Georgian College, program code HBNA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie, Orangeville, Owen Sound campus. This pathway prepares graduates for a life-long career as a Registered Nurse. Grounded in a vibrant urban and rural community, faculty work collaboratively with practice partners to provide diverse experiences for students to learn about the complexity of nursing in a modern healthcare environment. The role of nurses as leaders in healthcare delivery is taught from a practice-based framework where real life experiences are a focus of teaching and learning. Faculty and preceptors actively work with students to create opportunities for scholarship and professional growth which support the development of nurses who can serve as leaders and advocates for person-centered care. Graduates from this program obtain the additional designation of RN Prescriber. Georgian College is authorized by the College of Nurses of Ontario to provide RN Prescriber education. Your Honours BScN nursing degree from Georgian will open doors to careers in hospitals, long-term care, clinics or community health services. This community-based program reflects the specific health needs of local populations, including the elderly, Indigenous and Francophone peoples, as well as those with mental health challenges. This program is a pathway for those with previous nursing credentials. For individuals with no previous nursing knowledge, please check out Georgian''s four-year Honours Bachelor of Science – Nursing degree International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Hospitality - Hotel and Resort Operations Management', 'hospitality-hotel-resort-operations-management-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/hospitality-hotel-resort-operations-management', 'Ontario College Diploma, Co-op at Georgian College, program code HHRO, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. Turn your passion for people, travel, and excitement into a global career in hospitality! This dynamic two-year diploma prepares you for work in luxury resorts, five-star hotels, and top restaurant chains with hands-on training, industry certifications, and real-world experience. From day one, you''ll learn by doing, cooking and serving in a live campus restaurant, managing guest check-ins with hotel software, and visiting top regional resorts on exciting field trips. You''ll also complete a paid 560-hour co-op, connecting you directly with employers. Highlights include live training in restaurant, housekeeping, and front desk operations; certifications in Smart Serve, Food Safety, and First Aid/CPR; and support through a major hospitality career fair. Learn from experienced professors and gain tech-driven training with tools used by major hotel brands. Plus, you''ll have clear pathways into degree and post-grad programs. This program is your launchpad to a fast-paced, global hospitality career where every day is different. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Hospitality and Tourism Foundations', 'hospitality-tourism-foundations-georgian', 'CERTIFICATE', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/hospitality-tourism-foundations', 'Ontario College Certificate at Georgian College, program code HOSF, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. The Hospitality and Tourism Foundations is an eight-month, two-semester certificate program that introduces students to the fundamentals of Hospitality Management while offering the flexibility to explore specialized career paths. In addition to completing core foundational courses, students have the opportunity to select elective courses tailored to their individual interests and career goals. Elective options will include options from the already established Hotel and Resort, Tourism or Flight Services diploma programs. This one-year certificate emphasizes experiential, hands-on learning through live labs, simulation technology, and small class sizes led by industry professionals. Students will also participate in field excursions, including day and overnight trips, providing practical experience in real-world settings. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Human Resources Management', 'human-resources-management-georgian', 'CERTIFICATE', 'Business and Management', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/human-resources-management', 'Ontario College Graduate Certificate at Georgian College, program code HRMN, in the Business and Management academic area. Delivered in person at the Barrie campus. Today''s human resource professionals are leaders and managers of change. They respond to the challenges triggered by new trends in technology, increasing government involvement in the employer-employee relationship, workplace diversity, and globalization. The future belongs to organizations with human resource expertise that can lower labour costs, improve productivity, increase responsiveness to customers'' needs, and build employee commitment. As a graduate of this program, you will be ready to perform all human resources functions within the business environment. Demonstrating the skills and competencies such as the ability to communicate effectively collaborate with others and displaying initiative and perseverance, you will possess the required knowledge, skills, and abilities to be a key person within the organization. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Indigenous Community and Social Development', 'indigenous-community-social-development-georgian', 'DIPLOMA', 'Indigenous Studies', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/indigenous-community-social-development', 'Ontario College Diploma, Co-op at Georgian College, program code ICSD, in the Indigenous Studies academic area. Delivered in person at the Barrie campus. In this program, students focus on the planning, evaluation and administration of social/health care programs and services within Indigenous communities and organizations. Students study business and community development, health and well-being, language and culture while integrating cultural, social and health issues relevant to Indigenous peoples in Canada. Cultural teachings and smudging are integrated daily throughout each academic semester in social activities, individual program courses, and Traditional Teacher/Elder visits. Please note: Indigenous includes First Nations, Metis, Inuit and Non-Status People. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Interior Decorating', 'interior-decorating-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/interior-decorating', 'Ontario College Diploma at Georgian College, program code INDC, in the Design and Visual Arts academic area. Delivered hybrid at the Barrie campus. I nterior decorating is the art of creating distinctive interior spaces that respond to functional needs and address aesthetic perceptions. As a student, you focus on the use of space, beautification and furnishing of interiors, and the documentation of design concepts resulting in an overall package that conveys a sense of place. Using a variety of formats including lecture, studio and lab, you complete projects to interpret client requirements and create innovative interiors. You gain professional and entrepreneurial skills for industry and self-employment, as well as real life experience through participation in a field placement in the decorating field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Jewellery Design, Bench Skills and Business', 'jewellery-design-bench-skills-business-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/jewellery-design-bench-skills-business', 'Ontario College Diploma at Georgian College, program code JDBB, in the Design and Visual Arts academic area. Delivered hybrid at the Barrie campus. The Jewellery Design, Bench Skills and Business diploma program provides you with the hands-on experience and skills necessary for a successful career in the jewellery industry. With access to industry experts, seasoned faculty and studios equipped with the latest technologies, you gain valuable expertise in stone setting, jewellery repair, and the creation of custom jewellery using hand fabrication and finishing techniques. Your practical skillset is further complemented through the use of computer aided design (CAD) software, which is of growing importance in the jewellery industry. With first-hand experience working in and managing the campus jewellery store, this unique program helps you broaden your focus to sales, marketing, accounting and business practices suitable for small businesses, and for creating and managing an online presence. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Law Clerk', 'law-clerk-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/law-clerk', 'Ontario College Diploma at Georgian College, program code LCLR, in the Business and Management academic area. Delivered in person at the Barrie campus. As integral members of the legal team, law clerks work independently under the general supervision of a lawyer and assist with numerous tasks associated with the handling of diverse legal matters, including direct interaction with internal and external stakeholders. In this program, you learn to draft legal correspondence and memoranda and prepare various court documents in practice areas such as real estate, corporate, estates, civil litigation and family law, utilizing current legal software to produce documents to professional standards. You learn legal administration skills, substantive law, ethics, collaboration and professionalism. You engage in experiential learning through a field placement that reinforces and expands upon the knowledge and skills acquired in the classroom. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Maajii-Anishnaabemdaa (Start Speaking the Language)', 'maajii-anishnaabemdaa-georgian', 'CERTIFICATE', 'Indigenous Studies', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/maajii-anishnaabemdaa', 'Ontario College Certificate at Georgian College, program code MAAJ, in the Indigenous Studies academic area. Delivered in-person and hybrid option at the Barrie campus. The Maajii-Anishnaabemdaa certificate begins your foundational journey to speaking and understanding Anishnaabemowin, connecting you to Anishnaabe ways of being, traditional values, and history. Using an immersive approach and exploring themes such as home and community, you develop speaking, reading, and listening skills in Anishnaabemowin. You also learn how to write the language by studying writing systems and practicing Anishnaabemowin grammar structures. To build fluency and confidence in Anishnaabemowin, you practice vocabulary, speaking, and listening skills with classmates, Elders, and Knowledge Keepers, and through the use of immersive virtual reality (VR) technology. The program further embeds experiential learning opportunities to practice Anishnaabemowin within the community and through land-based activities, emphasizing the vital connection between language and culture. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Marine Engineering Technology', 'marine-engineering-technology-georgian', 'DIPLOMA', 'Marine Studies', 'Owen Sound', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/marine-engineering-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code MTCY, in the Marine Studies academic area. Delivered in person at the Owen Sound campus. Students are immersed in an internationally recognized co-operative marine engineering cadet program designed in co-operation with Transport Canada Marine Safety and Security (TCMSS) and Canada''s shipping companies. Students focus on developing competencies required to function as part of a shipboard marine engineering team. Content includes, and is based upon, the TCMSS Engineering Officer Education Training (EOET) program requirements. The final two semesters are open to anyone holding an STCW Reg. III/1 Marine Engineer Certificate of Competency. These students can apply for advanced standing exempting them from the first five semesters of the program. Upon completion of semesters six and seven, they may be exempted from written examinations for 2nd and Chief Engineer Officer. NOTE: This is a TCMSS approved program. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Marine Technology - Navigation', 'marine-technology-navigation-georgian', 'DIPLOMA', 'Marine Studies', 'Owen Sound', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/marine-technology-navigation', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code MNAV, in the Marine Studies academic area. Delivered in person at the Owen Sound campus. This program has been planned in co-operation with Transport Canada Marine Safety and Security (TCMSS) and Canada''s shipping companies. You acquire a complete education which will prepare you for the occupation of ship''s Navigation Officer. Skills include navigating merchant ships, assisting in cargo operations, and ensuring safety of life at sea and protection of the marine environment. The specialized competencies and work experience also provide you with the skills and knowledge necessary for employment in government and in other marine-related industries. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Massage Therapy', 'massage-therapy-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/massage-therapy', 'Ontario College Advanced Diploma at Georgian College, program code MASG, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. The philosophy and curriculum of this collaborative program incorporates and utilizes evidence-based practice, clinical decision making, and therapeutic relationships as the basis of massage therapy. Students work collaboratively with peers and faculty to develop massage knowledge and skills that meet the Inter-Jurisdictional Practice Competencies and Performance Indicators as set out by the Federation of Massage Therapy Regulatory Authorities of Canada. In the classroom, students focus on the theoretical frameworks that relate to massage and applied sciences. In the lab and clinic setting, students integrate knowledge from program courses to provide evidence-based, client-centred care. U nder the guidance of a Registered Massage Therapist, students both receive and perform treatments. Students engage in diverse practicum experiences by practicing in a variety of clinics and outreaches. Please note that students are required to provide their own transportation to practicum placements. Mission statement: Through a student-centred environment focused on success, Georgian''s Massage Therapy graduates are competent, professional therapists who are accountable for the standards of the profession, and are responsive to the needs of the consumer. Flexible progression: Massage Therapy is a fast-track program delivered in six consecutive semesters. There may be flexibility to take a break between semesters. Connect with your program co-ordinator to explore possibilities. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Mechanical Technician - Precision Skills', 'mechanical-technician-precision-skills-georgian', 'DIPLOMA', 'Skilled Trades', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/mechanical-technician-precision-skills', 'Ontario College Diploma, Co-op at Georgian College, program code MTPS, in the Skilled Trades academic area. Delivered in person at the Barrie campus. This program provides students with opportunities to acquire precision skills that are in high demand within the advanced manufacturing sector. Students learn to safely set-up and operate conventional machine tools and other complex machining equipment, such as CNC lathes, mills and accessories. They develop the knowledge and skills to manufacture components, assist with design of jigs and fixtures, tools, moulds and dies and perform troubleshooting to enact repairs on production tooling. Through experiential learning opportunities, students use accurate measuring and testing methods to ensure precision in a variety of manufactured components. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Mechanical Techniques - Marine Engine Mechanic', 'mechanical-techniques-marine-engine-mechanic-georgian', 'CERTIFICATE', 'Skilled Trades', 'Midland', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/mechanical-techniques-marine-engine-mechanic', 'Ontario College Certificate at Georgian College, program code MTME, in the Skilled Trades academic area. Delivered in person at the Midland campus. In this program, students prepare for a career as a Marine Engine Mechanic, Marine Engine Apprentice or Marina employee working on recreational boats in the Marine Industry. Students develop a concentrated understanding of marine and watercraft systems that includes gasoline and diesel engines, fuel management systems, engine electrical systems, marine direct current electrical systems, steering and hydraulic systems, drives, and propulsion systems. A significant hands-on component allows students to develop practical and technical skills to meet the current needs of the Recreational Marine industry, and provides a basis to respond to emerging trends in the field. Finally, students become effective communicators and problem solvers who have an awareness of environmental issues, effective customer service, and basic business operations. Upon completion, the graduate may return for additional technical training and specialization such as Mercury Marine and The American Boat and Yacht Council Certification courses. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Mechanical Techniques - Small Engine Mechanic', 'mechanical-techniques-small-engine-mechanic-georgian', 'CERTIFICATE', 'Skilled Trades', 'Midland', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/mechanical-techniques-small-engine-mechanic', 'Ontario College Certificate at Georgian College, program code MTSE, in the Skilled Trades academic area. Delivered in person at the Midland campus. Students prepare for a career as a Small Engine Mechanic, Powersports equipment technician or as an employee at a multi-line dealership. They develop a concentrated understanding of small to medium sized engines and related systems for off-road vehicles and powered equipment. This includes gasoline engines, diesel engines, fuel management systems, electrical systems, frames, steering and suspension systems, transmission and auxiliary power systems, braking systems, hydraulic systems and onboard computer systems. A significant hands-on component allows individuals to develop practical and technical skills to meet the current needs of the Small Engine and Powersports industries, and will provide a basis to respond to emerging trends in the field. Finally, students become effective communicators and problem solvers who will have an awareness of environmental issues, effective customer service, and basic business operations. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Medical Laboratory Assistant', 'medical-laboratory-assistant-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/medical-laboratory-assistant', 'Ontario College Certificate at Georgian College, program code MLBA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. The Medical Laboratory Assistant program offers students the skills and abilities to perform pre-analysis components of medical lab work under direct supervision of medical laboratory technologists in hospitals, physician''s offices and private medical laboratory settings. Through experiential learning opportunities, students become proficient in the collection of blood samples, performing ECGs, the use of laboratory equipment and being fluent in medical terminology. Communication and interpersonal skills are also developed in the program for patient interaction. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Medical Laboratory Technology', 'medical-laboratory-technology-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 3.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/medical-laboratory-technology', 'Ontario College Advanced Diploma at Georgian College, program code MLBT, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. The Medical Laboratory Technology program prepares students to become integral members of the health care team as Registered Medical Laboratory Technologists. Through a blend of classroom learning, laboratory activities and clinical placements, students develop the knowledge, technical and critical thinking skills essential to safely and reliably collect and analyze patient samples in a fast-paced clinical environment. Analysis of samples provides timely and critical information to support diagnostic decisions and to evaluate the efficacy of treatment plans. Students in this high-tech health care program learn to operate sophisticated equipment to measure components of blood and body fluids through course work related to clinical chemistry and clinical hematology. They prepare cultures of collected micro-organisms for identification as part of course work in clinical microbiology, and prepare tissue samples for histological study. Through hands-on practice, students perform blood typing and cross-matching of blood to support blood transfusions within the clinical environment, learn to draw blood safely from patients, and develop other collecting techniques related to the profession. This program is a great fit for students with keen interests in science, technology and health care, and a passion for solving problems. Students develop the organizational and technical skills to perform their work with efficiency, accuracy and precision in accordance with quality assurance guidelines for the profession. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Medical Skin Care Therapies', 'medical-skin-care-therapies-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'May', 'grad', 'https://www.georgiancollege.ca/academics/programs/medical-skin-care-therapies', 'Ontario College Graduate Certificate at Georgian College, program code MSCT, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. Students explore essential and advanced theory and practice skills related to the field of medical esthetics. Emphasis is placed on developing the knowledge, skills and judgement necessary to provide a treatment plan and make professional recommendations and referrals when appropriate. Students learn to work with relevant medical professionals in a safe and competent manner. The practice component is conducted in a lab/clinic environment where best practice, current regulations and protocols are adhered to. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Museum and Gallery Studies', 'museum-gallery-studies-georgian', 'CERTIFICATE', 'Design and Visual Arts', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/museum-gallery-studies', 'Ontario College Graduate Certificate at Georgian College, program code MUSM, in the Design and Visual Arts academic area. Delivered in person at the Barrie campus. As a student of the Museum and Gallery Studies program, you will acquire a comprehensive foundation in museum and gallery work. You will develop capabilities in the main technical areas common to all museums and galleries: conservation and collections management, exhibition design, public programming, interactive technology, and administration. By advancing your existing knowledge through a blend of engaging academic instruction and experiential learning opportunities such as technical practice and a co-op work placement, you will be prepared to understand the legacy of museums and galleries while being a part of the change that moves this field of study forward. Connecting theory with practice, the Museum and Gallery Studies program focuses on curatorial sustainability, equity and diversity in curriculum and action, and instilling collaborative approaches to problem-solving. You will receive hands-on experience working with The Campus Gallery and Georgian College''s extensive art collection. Networking with museum and gallery professionals, historians, and artists, you will create off-site exhibitions with local cultural institutions. After your coursework is complete, a four-month co-op work placement will prepare you for the next steps in your career in Museums and Galleries. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Occupational Therapist Assistant and Physiotherapist Assistant', 'occupational-therapist-assistant-physiotherapist-assistant-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/occupational-therapist-assistant-physiotherapist-assistant', 'Ontario College Diploma at Georgian College, program code OPTA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. Students are provided with the theoretical knowledge and practical skills necessary to function competently in the role of an Occupational Therapist Assistant and Physiotherapist Assistant (OTA and PTA) in a complex health care environment. They are prepared to work under the supervision of and in collaboration with occupational therapists and physiotherapists, and assist therapists to teach and enable clients to effectively cope with limitations in movement and daily functioning, whether temporary or permanent, during and following recovery. Students partake in a combination of practical and theoretical learning achieved through classroom, laboratory and field placements. Learning will take place with an inter-professional approach to meet the needs of clients in acute and community settings. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Office Administration - General', 'office-administration-general-georgian', 'CERTIFICATE', 'Business and Management', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/office-administration-general', 'Ontario College Certificate at Georgian College, program code OFAG, in the Business and Management academic area. Delivered in person at the Barrie campus. Students are prepared to assist in a wide variety of entry-level office settings by gaining skills and knowledge to support the management of an organization. By learning three key and interdependent functions: organization, processing information, and communication, students achieve a solid foundation to become an effective member of an office team. Students build technological competency through learning a variety of application packages utilized in businesses today. This program sets a basis for further educational growth and students may elect to transition for an additional year into enhanced and specialized learning leading to an Office Administration–Health Services or Office Administration-Executive diploma. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Office Administration - Health Services', 'office-administration-health-services-georgian', 'DIPLOMA', 'Business and Management', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/office-administration-health-services', 'Ontario College Diploma at Georgian College, program code OFAH, in the Business and Management academic area. Delivered in person at the Barrie campus. Students in this program acquire the knowledge and specialized skills required to successfully perform in the administrative health field. Students learn medical document production, medical terminology, transcription, human anatomy, medical ethics, and develop skills in workplace communication and patient relations. In addition, students learn Electronic Medical Records (EMR) and are introduced to health information management concepts. Qualifying students will have the exciting opportunity for hands-on learning through a fourth semester field placement within the local medical community. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Opticianry', 'opticianry-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/opticianry', 'Ontario College Diploma, Co-op at Georgian College, program code OPTI, in the Health, Wellness and Sciences academic area. Delivered hybrid at the Barrie campus. In this program, students experience a unique blend of health care and professional service. Through theory and practical experience in labs, students learn to competently dispense eyeglasses, contact lenses, low vision devices, as well as learn about basic refraction. Students gain a strong foundation of ocular sciences in optics and anatomy and are provided the expertise necessary to lay out and edge lenses for frame insertion, as well as repair, customize and modify eyewear to the patient/clients'' needs. Emphasis is also placed on critical thinking, problem solving, and entrepreneurial skills. Students learn how to use effective sales techniques and enhance communication and interpersonal skills in order to be successful in the optical retail environment. Upon successful completion of the academic and co-operative education semesters, students are eligible to write the national registration examinations (NACOR) which allow them, if successful, to practice in Canada as a Registered Optician. You may be invited to complete your co-op experiences in other communities, because your skills will be in demand all over Ontario and Canada. Be prepared to travel or relocate for your co-op work terms. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Paralegal', 'paralegal-georgian', 'CERTIFICATE', 'Business and Management', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/paralegal', 'Ontario College Graduate Certificate at Georgian College, program code PARL, in the Business and Management academic area. Delivered in person at the Barrie campus. Ontario is currently the only province in Canada whose law society regulates paralegals in the province. Licensed paralegals provide legal services to the public within a particular scope of practice. In this program, you will acquire an understanding of general principles of law, theoretical knowledge and practical skills to prepare you to appear before various legal forums such as Small Claims Court, Provincial Offences Court, the Ontario Human Rights Tribunal and the Landlord and Tenant Board. Conflict management strategies, entrepreneurial preparedness and ethics and professional responsibility are emphasized. You graduate prepared to apply to write the Law Society of Ontario''s licensing exam to become a paralegal in Ontario. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Paramedic', 'paramedic-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/paramedic', 'Ontario College Diploma at Georgian College, program code PARA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. As a student enrolled in Georgian''s Paramedic program, you are prepared with the knowledge and skills that allow you to work effectively and collaboratively in this fast- paced and intense health discipline. With a robust balance of practical experience and theoretical knowledge, you learn to manage medical and traumatic emergencies in the out-of-hospital setting with an emphasis on sciences, pharmacology, communication and providing patient care to a diverse population. You learn these skills in a variety of settings including the classroom, our simulation labs, hospital departments and with a comprehensive placement with a practicing paramedic. In addition, you learn about and how to prioritize mental and physical self-care in a demanding but very rewarding career. This program is highly competitive. Learn about admission requirements for highly competitive programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Personal Support Worker', 'personal-support-worker-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie, Orangeville, Owen Sound', 'CAD 17,170 to 18,170/year', 1.0, 'September, January, May', 'diploma', 'https://www.georgiancollege.ca/academics/programs/personal-support-worker', 'Ontario College Certificate at Georgian College, program code PSWR, in the Health, Wellness and Sciences academic area. Delivered hybrid at the Barrie, Orangeville, Owen Sound campus. The Personal Support Worker (PSW) program is a two semester Ontario College Certificate that provides you with the knowledge and practical skills to offer safe, supportive care to clients in settings such as private homes, long term care and acute care facilities. As a member of an interprofessional health care team, PSWs assist with daily living and the provision of person-centred care to individuals with a range of health conditions and/or individuals experiencing responsive behaviours. Through theory and hands-on lab classes, you learn how to provide a comfortable, safe environment for clients while assisting with personal care and home management. Two clinical placements in long term care and other healthcare settings, provide training in the delivery and documentation of care, and expand your ability to provide holistic, compassionate care throughout the lifespan to clients and their families. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Pharmacy Technician', 'pharmacy-technician-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/pharmacy-technician', 'Ontario College Diploma at Georgian College, program code PHRM, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. At Georgian College, you will gain the knowledge, skills, and confidence needed to excel as a pharmacy technician. Our program focusses on professionalism, safe patient care, and leadership through effective communication and collaboration. You will learn to work alongside pharmacy teams and healthcare professionals to support patients in achieving their health goals and ensure continuity of care while distributing high-quality pharmaceutical products. Through hands-on experiences, including simulation labs and placements in community and hospital pharmacies, you will be prepared to thrive in real-world settings. Plus, you will learn from expert faculty who are also practicing pharmacy professionals, ensuring your education is both practical and industry-relevant. Flexible progression: Would you like to finish the program earlier? The fast track options allows students to take consecutive semesters, completing the program in 16 months. Connect with your program co-ordinator to explore possibilities. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Plumbing Techniques', 'plumbing-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Midland', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/plumbing-techniques', 'Ontario College Certificate at Georgian College, program code PLTQ, in the Skilled Trades academic area. Delivered in person at the Midland campus. The Plumbing Techniques program offers both the theoretical knowledge and practical training required to perform basic plumbing tasks. Through a combination of in-class and hands-on learning, you will work individually and as part of a team to develop the fundamental skills required to start a career in the plumbing trade. You will engage in a variety of plumbing projects that include designing and drawing plans, implementing and working in adherence to National plumbing codes, and following health and safety protocols and practices, all of which are requirements of the plumbing trade. This is an exciting opportunity to gain an introduction to skills-based learning and trade knowledge, which can serve as a foundation for further education through pathways into other affiliated skilled trades programs or apprenticeships or gain entry-level employment in a related field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Police Foundations', 'police-foundations-georgian', 'DIPLOMA', 'Community Safety', 'Barrie, Owen Sound', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/police-foundations', 'Ontario College Diploma at Georgian College, program code PFPR, in the Community Safety academic area. Delivered hybrid at the Barrie, Owen Sound campus. Students engage in academic and practical courses to develop the knowledge and skills demanded by Canadian police services. Forensic crime scene investigation, interview skills, use of force theory and application, police powers, and crisis intervention techniques are areas of focus. The physical training and career preparation components of the program prepare students to meet the specific demands of police recruitment processes and a career in the field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Power Engineering Technology', 'power-engineering-technology-georgian', 'DIPLOMA', 'Engineering and Environmental Technology', 'Owen Sound', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/power-engineering-technology', 'Ontario College Advanced Diploma, Co-op at Georgian College, program code PETY, in the Engineering and Environmental Technology academic area. Delivered in person at the Owen Sound campus. Power Engineers operate high-energy industrial processes found in power plants in Canada and across the world. Power Engineers ensure that steam production, electrical generation, refrigeration and gas compression is safe, reliable, and efficient. As a power engineering student, you will learn in classrooms, labs, and using simulation. In the classroom you learn about power industry equipment design and the applied sciences that explain how machines work. You will get hands-on experience working in our on-site TSSA registered high-pressure steam power plant. You will operate a steam boiler, a refrigeration chiller, and a steam prime mover. You will also learn practical maintenance skills while working on pumps, compressors, valves and piping in our power systems lab. You will learn to operate and troubleshoot power plant processes in our power plant simulation lab. On your CO-OP you will work in industry and apply your academic knowledge. Power Engineering Technology (Coop) is an approved TSSA Operating (Power) Engineer training program for 4 th and 3 rd Class certifications. Graduates can complete our program with a nationally recognized power engineering certification, coop work experience and the skills needed to be successful in the power industry. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Practical Nursing', 'practical-nursing-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie, Owen Sound, Orangeville', 'CAD 16,990 to 29,200/year', 2.5, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/practical-nursing', 'Ontario College Diploma at Georgian College, program code PNRS, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie, Owen Sound, Orangeville campus. Students engage with philosophy and curriculum that incorporates and utilizes the concept of caring as the basis of nursing practice. Students work with experienced, caring faculty to gain the knowledge, skills and judgment required to work in today''s complex health care system. Students learn how to engage in safe, competent professional practice with high expectations of accountability, collegiality, collaboration, leadership and ethical care. Students experience high-quality, innovative nursing education both in the classroom and simulation laboratory settings. Engaging in a mix of individual and team learning activities, students focus on the lived experiences of individuals, families, groups and communities. Through our partnerships, clinical experiences in diverse healthcare settings are offered to allow students to integrate their knowledge into the care of clients across the lifespan. In order to provide quality practicum placements, students have the opportunity to be placed in a variety of agencies in the region. The Practical Nursing program is currently approved (Category 1, the highest ranking) by the College of Nurses of Ontario. Current graduates of this program are eligible to apply for registration as Registered Practical Nurses in Ontario. This program is highly competitive. Learn about admission requirements for highly competitive programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Pre-Engineering Techniques', 'pre-engineering-techniques-georgian', 'CERTIFICATE', 'Engineering and Environmental Technology', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/pre-engineering-techniques', 'Ontario College Certificate at Georgian College, program code PTEC, in the Engineering and Environmental Technology academic area. Delivered in person at the Barrie campus. Build your foundation in engineering with our hands-on Pre-Engineering Techniques program! This two-semester Ontario College Certificate prepares you with foundational skills for a future in engineering and technology. Through a mix of practical lab work and in-class learning, you''ll explore key concepts in electrical systems, construction and environmental practices, and advanced manufacturing. Working individually and in teams, you''ll develop problem-solving skills, learn to operate computer systems and assisted design (CAD) software, as well as how to apply safety and compliance standards essential to any engineering environment. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Pre-health Sciences Pathway to Advanced Diplomas and Degrees', 'pre-health-sciences-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie, Online, Owen Sound', 'CAD 17,170 to 18,170/year', 1.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/pre-health-sciences', 'Ontario College Certificate at Georgian College, program code PHPA, in the Health, Wellness and Sciences academic area. Delivered hybrid at the Barrie, Online, Owen Sound campus. In this Pre-health Sciences preparatory program, you develop life-long personal, professional and academic skills and habits to support success in your academic and career goals. Classroom studies in math, chemistry, physics, and biology are brought to life through your hands-on experience in Georgian College''s modern laboratory facilities. You explore current career opportunities in health care and the educational requirements, roles and responsibilities for each, including strategies that support equity, diversity, inclusion and belonging. Throughout the program, you also build problem-solving, critical thinking and communication skills. As a student in this program, you gain valuable learning, experience and insight into what is required to be successful in college studies. As an added bonus, you earn post-secondary course credits that may be eligible for transfer credits in future college programs. As a graduate of this program, you are prepared for success in further health care and medical sciences studies offered through advanced diploma and/or degree programs. Please note that all programs have their own minimum GPA requirements and completing the Pre-health Sciences program does not guarantee acceptance into other programs. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Pre-service Firefighter Education and Training', 'pre-service-firefighter-georgian', 'CERTIFICATE', 'Community Safety', 'Barrie', 'CAD 17,170 to 18,170/year', 1.5, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/pre-service-firefighter', 'Ontario College Certificate at Georgian College, program code FIRE, in the Community Safety academic area. Delivered in person at the Barrie campus. Immersed in a dynamic and challenging learning environment, students develop the ability to perform the duties of a firefighter. Through a blend of both theoretical and hands-on experience, students develop skills and knowledge of fire dynamics, building construction, fire suppression principles and practice, personal protective equipment, emergency medical response and fire prevention and public education. Students also explore theoretical concepts and safety considerations in technical rescue disciplines such as confined space, water and ice water rescue, rope rescue, and trench rescue. The Pre-Service Firefighter Education and Training program meets the following National Fire Protection Association (NFPA) Standards: NFPA 1001 Standard for Firefighter Professional Qualifications: Firefighter I and Firefighter II NFPA 1072 Standard for Competence of Responders to Hazardous Materials/Weapons of Mass Destruction Incidents NFPA 1035 Standard for Professional Qualifications for Fire and Life Safety Educator Level I International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Project Management - Information Technology', 'project-management-information-technology-georgian', 'CERTIFICATE', 'Computer Studies', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September, January', 'grad', 'https://www.georgiancollege.ca/academics/programs/project-management-information-technology', 'Ontario College Graduate Certificate at Georgian College, program code PMIT, in the Computer Studies academic area. Delivered hybrid at the Barrie campus. Project planning and information technology are essential drivers in today''s fast-paced, globally connected workplaces. Businesses across all sectors require professionals who can not only apply project management skills to a variety of IT contexts, but can also manage resource procurement processes and communicate contract expectations to interested and affected parties. As a graduate of the Project Management-Information Technology program, you''ll have gained the knowledge and skills to design, develop, and manage information technology projects that meet the needs of organizations, and apply quality assurance processes effectively. You''ll build your skills and proficiency in the principles of project management to work as part of an effective team that drives communication, leadership, and collaboration. By leveraging emerging technologies, you''ll be equipped to undertake a variety of IT projects across different management frameworks and tools. This program is ideal for individuals from diverse educational backgrounds and industries who seek to develop project management competencies. You''ll learn how to use AI-driven project tools and implement risk and security project strategies from project initiation to project closure. As a graduate, you''ll be prepared to manage IT projects across various industries and to meet the evolving demands of today''s businesses. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Protection, Security and Investigation', 'protection-security-investigation-georgian', 'DIPLOMA', 'Community Safety', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/protection-security-investigation', 'Ontario College Diploma at Georgian College, program code PSIN, in the Community Safety academic area. Delivered hybrid at the Barrie campus. Using a streamlined, four semester, continuous model approach, students develop specific knowledge and the skills necessary to meet the needs of a various rapidly evolving public and private industries in relation to safety and security. Areas of study include investigative techniques, intelligence assessment, understanding radicalization and extremism, crisis intervention, emergency management, physical security planning, leadership and cyber security. As a stand-alone program with areas of commonality between the Police Foundations and Community and Justice Services programs, students will acquire an overall understanding of the Canadian charter of rights, law enforcement, intelligence collection, the investigative process, mental health, crisis intervention, critical thinking and analysis to develop specialized knowledge and skills that are in demand within public and private sector industries. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Recreation and Leisure Services', 'recreation-leisure-services-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/recreation-leisure-services', 'Ontario College Diploma, Co-op at Georgian College, program code RELS, in the Hospitality, Tourism and Recreation academic area. Delivered hybrid at the Barrie campus. Students are introduced to skills and knowledge needed to succeed in recreation and leisure services. The curriculum includes community recreation, outdoor adventure, arts, culture, heritage, leisure, fitness, retirement activities, life enrichment in long term care, adaptive-therapeutic recreation, facility operations, programming and event planning. Business administration fundamentals are incorporated with courses in marketing, accounting, technology, human resources, entrepreneurship and research. Students develop skills through group work and presentations, and experiential learning opportunities include a paid co-operative work semester and field trips. Through the cooperative work semester, students could participate in a number of events or programs working with children to seniors. Students gain competencies in leadership and group facilitation by designing, delivering and evaluating diverse, inclusive, relevant, environmentally sustainable recreation leisure and wellness initiatives. The program includes a co-op work term giving paid workplace experience in the field of study. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Social Service Worker', 'social-service-worker-georgian', 'DIPLOMA', 'Human Services', 'Barrie, Orangeville, Owen Sound', 'CAD 16,990 to 29,200/year', 2.0, 'September, January, May', 'diploma', 'https://www.georgiancollege.ca/academics/programs/social-service-worker', 'Ontario College Diploma at Georgian College, program code SSWK, in the Human Services academic area. Delivered in person at the Barrie, Orangeville, Owen Sound campus. In this program, students develop the knowledge and skills required to effectively assume the role of a helping professional in the diverse and complex field of social services. Students are challenged to examine their beliefs and values and to promote social justice, human dignity, and equity when working with individuals, families, groups, and communities. Through the use of counselling labs, students practice communication skills and develop practical skills in assessment, interviewing, relationship building, group facilitation, and the use of various therapeutic approaches. Students gain knowledge about their role as social service workers through the study and application of the code of ethics and standards of practice, and evidenced-based decision-making in the field of social service work. Faculty are committed to a teaching and learning practice that embraces and promotes equity, diversity, inclusion and belonging, with an emphasis on Indigenous knowledge and learning. Other areas of study include mental health, trauma-informed practice, crisis intervention, community development, anti-oppressive practice, advocacy, social change, and social innovation. Students have the opportunity to engage with the community through experiential learning, social change initiatives and two field placements. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Sport Administration', 'sport-administration-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September, January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/sport-administration', 'Ontario College Diploma at Georgian College, program code SPRT, in the Hospitality, Tourism and Recreation academic area. Delivered in person at the Barrie campus. The Sport Administration program provides the knowledge, skills and experience students need to undertake professional roles in the sport and recreation industry. Students are introduced to the fundamentals of business administration through courses in accounting, marketing, technology, research, and entrepreneurship, and they strengthen their ability to improve organizational outcomes using data leverage in a sports analytics course. Furthermore, operations in sports organization are developed through specialized courses in program planning, tournament and league scheduling, sponsorship, fundraising, fitness operations, and facility management. While engaging in community leadership opportunities and field placements, students apply their skills to real-world settings and build meaningful industry connections. Graduates of the program find themselves well-equipped to pursue careers in sport program coordination, operations and facility management, sport marketing, community recreation, and sport development. They may also pursue further education opportunities in this field. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Sport and Recreation Facility Management', 'sport-recreation-facility-management-georgian', 'DIPLOMA', 'Hospitality, Tourism and Recreation', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/sport-recreation-facility-management', 'Ontario College Diploma at Georgian College, program code SRFM, in the Hospitality, Tourism and Recreation academic area. Delivered hybrid at the Barrie campus. In the two-year Sport and Recreation Facility Management Diploma Program, you''ll be equipped with the knowledge and skills required for successful careers in recreation and facility management. Program courses integrate both theoretical concepts with practical applications, so that you''ll focus on the effective operation and management of municipal, private, and commercial recreation facilities. You''ll build the essential business and administrative skills required for the day-to-day operations in a sport and recreational facility, as well as knowledge of safety standards and risk planning to support the safe management of facilities. As a graduate of this program, you''ll develop the leadership and organizational skills necessary to manage a wide range of facility operations, from ice management to recreation planning, in environments ranging from community centers to sports complexes. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Therapeutic Recreation', 'therapeutic-recreation-georgian', 'CERTIFICATE', 'Human Services', 'Barrie', 'CAD 17,900 to 19,280/year', 1.0, 'September', 'grad', 'https://www.georgiancollege.ca/academics/programs/therapeutic-recreation', 'Ontario College Graduate Certificate at Georgian College, program code TREC, in the Human Services academic area. Delivered hybrid at the Barrie campus. Recreation Therapy is a dynamic and unique health care profession that allows clinicians to practice with flexibility, and creativity. You learn to provide client centered, strength-based services using the recreation therapy process that emphasizes equity, diversity, inclusion and belonging. You acquire the skills to complete client assessments and to plan, implement, evaluate and document group and individual recreation therapy programs. Through a number of experiential learning opportunities, you develop leadership and programming skills. A variety of techniques are explored in order to assist individuals to participate in meaningful recreation and leisure experiences to achieve health related goals, improve functional ability, and increase quality of life. Graduates of this program are eligible to become registered members of Therapeutic Recreation Ontario (R/TRO). Membership type will depend on the postsecondary credentials they hold: R/TRO for graduates with degrees R/TRO DIP for graduates with diplomas Graduates may also apply to become a Certified Therapeutic Recreation Specialist (CTRS) using one of two specific pathways ( equivalency path A or B ). International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Veterinary Assistant', 'veterinary-assistant-georgian', 'CERTIFICATE', 'Health, Wellness and Sciences', 'Barrie', 'CAD 17,170 to 18,170/year', 1.0, 'January', 'diploma', 'https://www.georgiancollege.ca/academics/programs/veterinary-assistant', 'Ontario College Certificate at Georgian College, program code VETA, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. The Veterinary Assistant certificate program prepares you to assist veterinary professionals in the practice of veterinary medicine in animal care settings. Throughout the program, you gain the knowledge and skills required to support veterinary professionals including safe handling and restraint techniques, general care of companion animals and administrative and reception duties. Using the knowledge learned in your lecture classes, labs, and simulation, you develop basic diagnostic laboratory techniques, radiography, surgical support procedures, and client service skills. Take a 360-degree tour of the clinic. Did you know? Beginning in summer 2026 and fall 2026, classroom and theory courses for the Veterinary Assistant and Veterinary Technician programs will be delivered at the Barrie Campus as planned. To ensure students continue to train in an accredited clinical environment, clinic days are planned to temporarily take place at the existing veterinary clinic in Orillia until the new permanent clinic in Barrie is complete. What to expect: Students will have access to the clinic building and parking. Students are required to arrange their own transportation between the Barrie and Orillia campuses. Bus transportation, ride sharing and other support options will be shared to support student planning. As plans continue for a new, state-of-the-art facility in Barrie, we''ll share timelines and updates as soon as they''re available. In the meantime, Georgian remains committed to maintaining program quality, accreditation standards and providing timely communication to students, including details about specific clinic days. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Veterinary Technician', 'veterinary-technician-georgian', 'DIPLOMA', 'Health, Wellness and Sciences', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/veterinary-technician', 'Ontario College Diploma at Georgian College, program code VETN, in the Health, Wellness and Sciences academic area. Delivered in person at the Barrie campus. This program provides an opportunity for students to acquire the skills, knowledge and attitudes required to be an integral member of a veterinary health care team. Students explore the range of activities carried out in companion and large animal practices, animal shelters, research facilities, zoos or wildlife facilities. Applying a humane approach to veterinary education, student learning includes theory, labs, simulation, advanced models, and clinical practice in our on-site veterinary hospital to develop the requisite competencies to provide medical and nursing care to animals. Clinical experience in various practice settings, with live animals, allows students to apply knowledge in the care and handling of animals. This program is highly competitive. Learn about admission requirements for highly competitive programs. Did you know? Beginning in summer 2026 and fall 2026, classroom and theory courses for the Veterinary Assistant and Veterinary Technician programs will be delivered at the Barrie Campus as planned. To ensure students continue to train in an accredited clinical environment, clinic days are planned to temporarily take place at the existing veterinary clinic in Orillia until the new permanent clinic in Barrie is complete. What to expect: Students will have access to the clinic building and parking. Students are required to arrange their own transportation between the Barrie and Orillia campuses. Bus transportation, ride sharing and other support options will be shared to support student planning. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Video and Motion Graphics Production', 'video-motion-graphics-production-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/video-motion-graphics-production', 'Ontario College Diploma at Georgian College, program code VMGP, in the Design and Visual Arts academic area. Delivered hybrid at the Barrie campus. Georgian College''s Video and Motion Graphics Production program is a two-year diploma designed to provide you with the technical skills, creative expertise, and extensive knowledge to create compelling content for platforms such as social media, video-sharing websites, commercial, and educational outlets. Through a combination of hands-on and experiential learning, you''ll learn to produce engaging video and motion graphic content that meet today''s media demands all while focusing on the importance of industry regulations, ethical practices, and safety protocols. This program is designed to guide you through the entire production process, from conceptualizing and storyboarding ideas to capturing and editing high-quality video and audio that delivers professional-quality motion graphics. You''ll learn essential techniques in lighting, composition, camera control, and audio recording while exploring emerging technologies like virtual and augmented reality to prepare for the future of immersive media. Additionally, you''ll learn media production management operations, including managing and maintaining digital archive systems, documenting projects, and developing business plans. The program culminates in a capstone course where you''ll apply your skills to deliver a professional product to potential clients and employers. Upon graduation, you''ll have an extensive portfolio that showcases your creative and technical abilities and positions yourself as a sought-after creator. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Visual and Digital Media Arts', 'visual-digital-media-arts-georgian', 'DIPLOMA', 'Design and Visual Arts', 'Barrie', 'CAD 16,990 to 29,200/year', 2.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/visual-digital-media-arts', 'Ontario College Diploma at Georgian College, program code VDMA, in the Design and Visual Arts academic area. Delivered in-person and hybrid option at the Barrie campus. In this program, students develop their creative abilities and artistic skills using the latest digital tools and a variety of traditional media. Through a combination of creative course content and hands-on studio practice, students develop their interests and skills in a variety of techniques and media, including drawing, painting, sculpture, printmaking, digital art, 3D modelling, 3D printing, photography, and extended reality (VR, AR) that help bring their artistic vision to life. Experiential art studios and unique media labs provide a hands-on environment to foster essential visual art skills. In our Campus Gallery, students engage with the work of contemporary artists as well as have opportunities to showcase their own work. Through immersive and leading-edge art education, students foster critical thinking, social innovation, and entrepreneurial skills, which are essential for success within the diverse professions in the visual arts. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.'),
  ('Welding Techniques', 'welding-techniques-georgian', 'CERTIFICATE', 'Skilled Trades', 'Midland, Owen Sound', 'CAD 17,170 to 18,170/year', 1.0, 'September', 'diploma', 'https://www.georgiancollege.ca/academics/programs/welding-techniques', 'Ontario College Certificate at Georgian College, program code WETC, in the Skilled Trades academic area. Delivered in person at the Midland, Owen Sound campus. Are you looking for a challenging and rewarding career in welding and metal fabrication? The Welding Techniques program prepares you to enter the workplace with an exceptional skill set that is in high demand. You acquire comprehensive welding skills through hands-on practical labs using the latest equipment in our state-of-the-art facility. You create and read blueprints and gain an understanding of metals and their characteristics. In addition to the solid theoretical and hands-on practical welding knowledge, you gain experience in safe work practices and weld inspection methods from well-seasoned, experienced Canadian Welding Bureau qualified instructors. Upon successful completion of this program, you are eligible to test for the Canadian Welding Bureau Qualifications based on your level of competence. International tuition is published as a range for this credential type rather than a single figure, and some programs carry additional program-specific fees.')
) as v(name, slug, degree_level, field, campus, tuition, duration, intake, entry_key,
  learn_more_url, description);

-- Replace the 2 invented scholarships with Georgian's real international entrance award.
delete from public.scholarships
where university_id = (select id from public.universities where slug = 'georgian-college');

insert into public.scholarships (id, university_id, name, type, description, value, learn_more_url,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.type::"ScholarshipType", v.description, v.value,
  'https://www.georgiancollege.ca/international/finance-and-fees/', now(), now()
from (select id from public.universities where slug = 'georgian-college') as uni,
(values
  ('International Entrance Scholarship', 'MERIT_BASED', 'Awarded automatically to new, eligible international students entering select programs, with no separate application. The amount depends on the credential: CAD 4,000 for eligible two-year degree or graduate certificate programs, CAD 3,000 for eligible two or three-year diploma and advanced diploma programs, and CAD 250 for eligible one-year graduate certificate programs. Eligibility is limited to the programs listed by Georgian each intake.', 'CAD 250 to CAD 4,000')
) as v(name, type, description, value);

-- Rewrite the admission steps with Georgian's actual process (international applicants use
-- their own portal, not ontariocolleges.ca, and the English requirement varies by credential).
with uni as (select id from public.universities where slug = 'georgian-college')
update public.admission_steps s
set title = v.title, description = v.description, updated_at = now()
from uni, (values
  (1, 'Choose Your Program and Check Availability', 'Pick a program from Georgian''s 130-plus full-time offerings and confirm it is open to international students for your intended intake, since availability varies by term. Most programs start in September, with a smaller number of January and May intakes.'),
  (2, 'Apply Through the International Applicant Portal', 'International applicants apply through Georgian''s dedicated applicant portal rather than ontariocolleges.ca. The application fee is CAD 100. Upload secondary school transcripts for diploma and certificate programs, or college and university transcripts plus a resume and letter of intent for graduate certificates.'),
  (3, 'Meet the English Requirement and Accept Your Offer', 'Submit English test results no more than two years old: IELTS Academic 6.0 for diplomas and certificates, or 6.5 for degrees and graduate certificates, with equivalent TOEFL iBT, PTE, Duolingo, CAEL and Cambridge scores accepted. Once you receive an offer, confirm your seat with the non-refundable deposit of CAD 2,500.'),
  (4, 'Apply for Your Study Permit', 'Apply to Immigration, Refugees and Citizenship Canada using your Letter of Acceptance, Provincial Attestation Letter and proof of deposit payment. Georgian''s Designated Learning Institution number is O19395677361. Allow four to six months, as processing times vary by country.')
) as v(step_number, title, description)
where s.university_id = uni.id and s.step_number = v.step_number;

commit;
